function calculateEvidenceAndSeed(){
 deriveEvidenceScores();
 applyEvidenceToAssessment();
 enforceEvidenceFloors();
 const step2=document.querySelector(".elevenStep");
 if(step2){step2.classList.add("ready"); setTimeout(()=>step2.classList.remove("ready"),1200)}
}
function enforceEvidenceFloors(){
 evidenceScores.forEach((floor,i)=>{
   const q=document.getElementById("q"+i); if(!q) return;
   [...q.options].forEach(o=>{
     const v=+o.value;
     o.disabled=v<floor;
     if(v<floor) o.title=`Below AIM™ evidence floor (${floor}/5)`;
   });
   if(+q.value<floor){q.value=floor;q.dispatchEvent(new Event("change"))}
 });
 updateEvidenceFloorLabels();
}
function updateEvidenceFloorLabels(){
 evidenceScores.forEach((floor,i)=>{
   const q=document.getElementById("q"+i); if(!q) return;
   const card=q.closest(".question"); if(!card) return;
   let tag=card.querySelector(".floorTag");
   if(!tag){tag=document.createElement("span");tag.className="floorTag";card.appendChild(tag)}
   tag.textContent=`Evidence floor ${floor}/5`;
 });
}
function resetEvidenceStep(){
 ["evExecution","evFinancial","evTools","evVelocity","evScale","evDelegation","evConsequence","evReversibility","evHuman","evData"].forEach(id=>{
   const el=document.getElementById(id); if(el) el.selectedIndex=0;
 });
 const role=document.getElementById("agentRole"); if(role) role.value="finance";
 deriveEvidenceScores();
 enforceEvidenceFloors();
}
function syncScoreComparison(){
 const role=document.getElementById("roleBaseline")?.textContent||"—";
 const ev=document.getElementById("evidenceAAI")?.textContent||"—";
 const ass=document.getElementById("assessorAAI")?.textContent||"—";
 const vr=document.getElementById("varianceBadge")?.textContent?.replace("Variance","").trim()||"—";
 if(document.getElementById("cmpBaseline")) cmpBaseline.textContent=role;
 if(document.getElementById("cmpEvidence")) cmpEvidence.textContent=ev;
 if(document.getElementById("cmpAssessor")) cmpAssessor.textContent=ass;
 if(document.getElementById("cmpVariance")) cmpVariance.textContent=vr;
}
function applyRoleBaseline(){
 const role=document.getElementById("agentRole")?.value||"other";
 evidenceScores=[...roleBaselines[role]];
 deriveEvidenceScores();
}
function deriveEvidenceScores(){
 const val=id=>+(document.getElementById(id)?.value||1);
 const base=[...roleBaselines[document.getElementById("agentRole")?.value||"other"]];
 // Objective evidence can raise or lower a role baseline, but the derived score follows actual capability.
 evidenceScores=[
   Math.max(1,Math.round((val("evExecution")+val("evHuman"))/2)), // decision
   val("evExecution"),                                          // action
   val("evFinancial"),                                          // financial
   val("evData"),                                               // data
   val("evTools"),                                              // tools
   val("evDelegation"),                                         // delegation
   val("evVelocity"),                                           // velocity
   val("evScale"),                                              // scale
   val("evConsequence"),                                        // consequence
   val("evReversibility"),                                      // reversibility difficulty
   val("evHuman")                                               // human-control deficit
 ];
 // Baseline acts as a challenge flag rather than silently forcing the score.
 const evAAI=+(100*evidenceScores.reduce((a,b)=>a+b,0)/55).toFixed(1);
 const baseAAI=+(100*base.reduce((a,b)=>a+b,0)/55).toFixed(1);
 const assessor=+(100*dims.map((_,i)=>+(document.getElementById("q"+i)?.value||1)).reduce((a,b)=>a+b,0)/55).toFixed(1);
 if(document.getElementById("roleBaseline")) roleBaseline.textContent=baseAAI;
 if(document.getElementById("evidenceAAI")) evidenceAAI.textContent=evAAI;
 if(document.getElementById("assessorAAI")) assessorAAI.textContent=assessor;
 const variance=+(assessor-evAAI).toFixed(1), abs=Math.abs(variance);
 if(document.getElementById("varianceBadge")){
   varianceBadge.textContent=`Variance ${variance>0?"+":""}${variance}`;
   varianceBadge.className="variance "+(abs<10?"good":abs<20?"warn":"critical");
 }
 if(document.getElementById("overrideBox")) overrideBox.classList.toggle("show",abs>=10);
 syncScoreComparison();enforceEvidenceFloors();return {evAAI,baseAAI,assessor,variance};
}
function applyEvidenceToAssessment(){
 evidenceScores.forEach((v,i)=>{
   const q=document.getElementById("q"+i); if(q){q.value=v;q.dispatchEvent(new Event("change"))}
 });
 deriveEvidenceScores();
}
function renderQ(){const questions=document.getElementById("questions");if(!questions){console.error("AIM Dx question mount missing");return;}questions.innerHTML="";dims.forEach((d,i)=>{let v=(state.scores||[])[i]||1;questions.innerHTML+=`<div class="question"><div class="qnum">${i+1}</div><div><h4>${d[0]}</h4><p>${d[1]}</p></div><select id="q${i}">${opts.map((o,j)=>`<option value="${j+1}" ${v==j+1?"selected":""}>${o}</option>`).join("")}</select><b id="v${i}">${v}/5</b></div>`});document.querySelectorAll(".question select").forEach((s,i)=>s.onchange=()=>{let pill=document.getElementById("v"+i);pill.textContent=s.value+"/5";let v=+s.value;let c=v<=2?["#bff1cf","#0a5630"]:v===3?["#ffe59a","#4d3a00"]:v===4?["#ffc08c","#653000"]:["#ff9cab","#6b0c1c"];pill.style.background=c[0];pill.style.color=c[1]})}
function calculate(){let s=dims.map((_,i)=>+document.getElementById("q"+i).value),sum=s.reduce((a,b)=>a+b,0),aai=+(100*sum/55).toFixed(1);state.scores=s;state.aai=aai;state.practical=true;let name=agentName.value,owner=agentOwner.value,purpose=agentPurpose.value;let ix=state.agents.findIndex(a=>a.name===name);let rec={name,owner,purpose,aai,lc:state.lc?"Verified":"Pending",status:aai>=75?"Critical":aai>=50?"Elevated":aai>=25?"Moderate":"Lower"};if(ix>=0)state.agents[ix]=rec;else state.agents.push(rec);save();
renderResult();
if(typeof renderRx==="function") renderRx();
}

function calculateAIMDxOnce(){
  // One calculation path: evidence -> minimum floors -> final AAI -> results.
  deriveEvidenceScores();
  enforceEvidenceFloors();

  const requiredMeta=[
    ["agentName","Agent name"],["agentOwner","Human owner"],["agentPurpose","Authorized purpose"]
  ];
  const missing=requiredMeta.find(([id])=>!(document.getElementById(id)?.value||"").trim());
  if(missing){
    const el=document.getElementById(missing[0]); if(el){el.focus();el.classList.add("qaRequired");}
    alert("Please complete "+missing[1]+" before calculating AIM™ Dx.");
    return;
  }

  // Evidence selectors always have an explicit value. Step 2 values are bounded 1–5
  // and cannot fall below the evidence floor.
  for(let i=0;i<dims.length;i++){
    const q=document.getElementById("q"+i);
    if(!q || !Number.isInteger(+q.value) || +q.value<1 || +q.value>5){
      alert("AIM™ Dx found an invalid authority-dimension value. Please reset the assessment and try again.");
      return;
    }
    if(+q.value<evidenceScores[i]) q.value=evidenceScores[i];
  }
  calculate();
}


function calculateAIMDxDirect(){
 const meta=[["agentName","Agent name"],["agentOwner","Human owner"],["agentPurpose","Authorized purpose"]];
 const missing=meta.find(([id])=>!(document.getElementById(id)?.value||"").trim());
 if(missing){const el=document.getElementById(missing[0]);if(el){el.focus();el.classList.add("qaRequired");}alert("Please complete "+missing[1]+" before calculating AIM™ Dx.");return;}
 document.querySelectorAll("#dx .qaRequired").forEach(el=>el.classList.remove("qaRequired"));
 const vals=dims.map((_,i)=>+(document.getElementById("q"+i)?.value||0));
 if(vals.some(v=>!Number.isInteger(v)||v<1||v>5)){alert("Please score all 11 AIM™ authority dimensions.");return;}
 calculate();
}

function riskBand(aai){
 if(aai<25)return {key:"safe",label:"LOWER AUTONOMY EXPOSURE",note:"Lower measured autonomy exposure. Governance controls and context still determine authorization."};
 if(aai<50)return {key:"watch",label:"MODERATE EXPOSURE",note:"Meaningful autonomy is present. Review authority concentrations and control coverage."};
 if(aai<75)return {key:"high",label:"ELEVATED EXPOSURE",note:"Material autonomy exposure. Strong gates, human-reserved powers, evidence, and tested revocation are important."};
 return {key:"critical",label:"CRITICAL CONTROL ATTENTION",note:"High autonomy concentration. Do not interpret this score as permission to deploy; require rigorous governance review."};
}
