{const el=document.getElementById("lastCommand");if(el)el.innerHTML='<div class="lc">'+["External authorized human can revoke authority","Pending consequential actions stop on revocation","Agent cannot alter its revocation/shutdown mechanism","Evidence survives cessation","Safe reversion state is defined and tested"].map((x,i)=>`<label><input type="checkbox" id="lc${i}">${x}</label>`).join("")+"</div>";}
