function answerMission(choice,btn){let m=missions[currentMission],ok=choice===m.answer;state.missionAnswers[currentMission]=ok;save();document.querySelectorAll("#missionChoices button").forEach(x=>x.classList.remove("right","wrong"));btn.classList.add(ok?"right":"wrong");missionMsg.innerHTML=`<div class="explain"><b>${ok?"Correct command decision.":"Incorrect command decision."}</b><br>${m.why}</div>`}
function startExam(){examAnswers={};exam.classList.remove("hidden");exam.innerHTML=`<div class="sectionHead"><div><span class="eyebrow">PROTOTYPE EXAM</span><h3>10-Question AIM-CP Knowledge Check</h3><p>Production release is planned as a larger randomized exam bank.</p></div></div>`+examBank.map((q,qi)=>`<div class="examQ"><b>${qi+1}. ${q.q}</b>${q.a.map((a,ai)=>`<button onclick="recordExam(${qi},${ai},this)">${a}</button>`).join("")}</div>`).join("")+`<button class="primary" onclick="gradeExam()">Submit Exam</button><div id="examMsg"></div>`}
function recordExam(q,a,btn){examAnswers[q]=a;btn.parentElement.querySelectorAll("button").forEach(x=>x.style.outline="");btn.style.outline="2px solid #0c7165"}
function gradeExam(){let correct=examBank.reduce((n,q,i)=>n+(examAnswers[i]===q.correct?1:0),0),score=correct/examBank.length*100;state.examScore=score;state.exam=score>=80;save();examMsg.innerHTML=`<p class="examScore">${score.toFixed(0)}%</p><p class="${state.exam?"good":"bad"}">${state.exam?"PASS — prototype exam gate complete.":"NOT YET PASSED — 80% required."}</p>`}
function renderAgents(){agentRows.innerHTML=state.agents.map(a=>`<tr><td><b>${a.name}</b></td><td>${a.owner}</td><td>${a.purpose}</td><td>${a.aai??"—"}</td><td>${a.lc}</td><td><span class="status ${(a.status==="Attention"||a.status==="Critical")?"attn":""}">${a.status}</span></td></tr>`).join("")}
function newAgent(){go("dx");agentName.value="New AI Agent";agentOwner.value="";agentPurpose.value="";resetDx()}
function renderExecutiveVisuals(){
 let a=state.aai;
 if(a==null){
   dialScore.textContent="—"; dialBand.textContent="Run AIM™ Dx to establish an AAI";
   dialBand.className="dialBand none";
   dialNeedle.style.transform="rotate(0deg)";
   dialNeedle.style.background="#8aa0aa";
   heatMap.innerHTML=dims.map(d=>`<div class="heatCell heatNone"><b>${d[0]}</b><span>—</span></div>`).join("");
   return;
 }
 let r=riskBand(a);
 dialScore.textContent=a.toFixed(1);
 dialBand.textContent=r.label;
 dialBand.className=`dialBand ${r.key}`;
 const riskColors={safe:"#25a866",watch:"#f2c94c",high:"#f28c28",critical:"#d64545"};
 dialNeedle.style.background=riskColors[r.key];
 dialNeedle.style.transform=`rotate(${a*1.8}deg)`;
 let s=state.scores||[];
 heatMap.innerHTML=dims.map((d,i)=>{let v=s[i];return `<div class="heatCell ${v?"heat"+v:"heatNone"}"><b>${d[0]}</b><span>${v?v+"/5":"—"}</span></div>`}).join("");
}
function updateAll(){
 try{renderAcademy();}catch(e){console.warn("Academy render skipped",e);}
renderExecutiveVisuals();let done=Object.keys(state.missionAnswers).length,correct=Object.values(state.missionAnswers).filter(Boolean).length,missionPct=missions.length?done/missions.length:0,modulePct=state.mods.length/mods.length;let overall=Math.round(modulePct*40+missionPct*30+(state.exam?15:0)+(state.practical?10:0)+(state.lc?5:0));academyProgress.textContent=overall+"%";mTraining.textContent=overall+"%";missionsDone.textContent=done+"/"+missions.length;missionAccuracy.textContent=done?Math.round(correct/done*100)+"%":"—";modulesDone.textContent=state.mods.length+"/10";readiness.textContent=overall>=90?"Qualification Ready":overall>=60?"Advancing":"Developing";heroAAI.textContent=state.aai??"—";renderAgents();mAgents.textContent=state.agents.length;mAttention.textContent=state.agents.filter(a=>(a.status==="Attention"||a.status==="Critical")).length;let verified=state.agents.filter(a=>a.lc==="Verified").length;mLC.textContent=Math.round(verified/state.agents.length*100)+"%";let missionGate=done===missions.length && correct/done>=.8;let all=state.mods.length===mods.length&&missionGate&&state.exam&&state.practical&&state.lc;gates.innerHTML=[[`Academy modules`,state.mods.length===mods.length],[`Command missions (≥80% accuracy)`,missionGate],[`Certification exam (≥80%)`,state.exam],[`Practical AIM™ Dx case`,state.practical],[`Last Command verification`,state.lc]].map(x=>`<div class="gate"><span>${x[0]}</span><b class="${x[1]?"good":"bad"}">${x[1]?"Complete ✓":"Incomplete"}</b></div>`).join("");credentialId.textContent=all?"AIM-CP-PROTOTYPE-0001":"AIM-CP-[qualification required]"}
renderQ();
renderResult();
try{renderMods();updateAll();}catch(e){console.warn("Non-Dx module initialization skipped:",e);}



const rxControlMap=[
 {name:"Decision Autonomy", fix:"Move consequential decisions behind explicit approval gates; allow autonomous recommendations only within pre-approved rules.", effect:"Reduces independent decision authority."},
 {name:"Action Authority", fix:"Define enforceable A/G/H/X action boundaries and technically block prohibited actions.", effect:"Reduces what the agent can cause directly."},
 {name:"Financial Authority", fix:"Set transaction and aggregate ceilings; require human or dual approval above thresholds; prohibit autonomous changes to payment destinations.", effect:"Reduces autonomous financial consequence."},
 {name:"Data Authority", fix:"Apply minimum-necessary access, purpose restrictions, field-level controls, retention limits, and immutable access logging.", effect:"Reduces data reach and misuse exposure."},
 {name:"Tool & Infrastructure Access", fix:"Use least-privilege service identities, segmented credentials, environment restrictions, and separate execution from administration.", effect:"Reduces system reach and blast radius."},
 {name:"Delegation Depth", fix:"Prevent self-expansion of authority; restrict sub-agent creation and require inherited authority limits for every delegated task.", effect:"Reduces uncontrolled authority propagation."},
 {name:"Execution Velocity", fix:"Add rate limits, transaction throttles, anomaly tripwires, cooling-off periods, and automatic pause conditions.", effect:"Creates time for detection and intervention."},
 {name:"Operational Scale", fix:"Cap populations, accounts, systems, locations, or transactions per run; use staged rollout and bounded operating scopes.", effect:"Reduces maximum blast radius."},
 {name:"Consequence Severity", fix:"Reserve irreversible or high-consequence actions for humans and require escalation before consequential execution.", effect:"Keeps the highest consequences outside autonomous control."},
 {name:"Reversibility", fix:"Add rollback, transaction reversal, versioned state, recovery procedures, and safe reversion testing before production.", effect:"Improves recovery when an action is wrong."},
 {name:"Human-Control Deficit", fix:"Install external revocation, independent monitoring, automatic tripwires, cessation verification, and a tested safe-state procedure.", effect:"Strengthens the human ability to stop the agent."}
];
function rxBandLabel(a){return a<25?"Lower Autonomy Exposure":a<50?"Moderate Exposure":a<75?"Elevated Exposure":"Critical Control Attention"}
function rxSeverity(s){return s>=5?"Critical":s===4?"High":s===3?"Moderate":"Lower"}
function rxMeta(){
 return {
  name:(document.getElementById("agentName")?.value||"This AI agent").trim(),
  owner:(document.getElementById("agentOwner")?.value||"the accountable human owner").trim(),
  purpose:(document.getElementById("agentPurpose")?.value||"its authorized purpose").trim()
 };
}
function rxDriverExplanation(x){
 const n=x.name;
 const m={
 "Decision Autonomy":"The agent can make material decisions with limited human intervention.",
 "Action Authority":"The agent can translate decisions into real-world actions rather than only recommendations.",
 "Financial Authority":"The agent can create, approve, commit, move, or influence financial value.",
 "Data Authority":"The agent can access or use sensitive, broad, or consequential data.",
 "Tool & Infrastructure Access":"The agent has access to systems or tools that can materially affect operations.",
 "Delegation Depth":"The agent can delegate work or propagate authority to other agents or processes.",
 "Execution Velocity":"The agent can act faster than ordinary human review and intervention cycles.",
 "Operational Scale":"A single agent decision can affect a broad population, workload, system, or operating scope.",
 "Consequence Severity":"A wrong or manipulated action could create material operational, financial, legal, safety, or stakeholder consequences.",
 "Reversibility":"Actions may be difficult, slow, costly, or impossible to reverse after execution.",
 "Human-Control Deficit":"Human intervention may occur too late, or revocation may not be sufficiently independent of the agent."
 };
 return m[n];
}

function rxPurposeContext(meta){
 const t=((meta.name||"")+" "+(meta.purpose||"")).toLowerCase();
 if(/payable|invoice|payment|vendor|procure|purchase|financial|finance|account/.test(t)) return {domain:"financial",noun:"financial transactions",human:"material payments, vendor banking changes, exceptions, and release of funds"};
 if(/clinical|patient|medical|health|diagnos|treatment|medication/.test(t)) return {domain:"healthcare",noun:"patient or clinical actions",human:"diagnosis/treatment decisions, medication changes, and other high-consequence clinical actions"};
 if(/cyber|security|incident|firewall|credential|network|endpoint/.test(t)) return {domain:"cybersecurity",noun:"security and infrastructure actions",human:"destructive containment, privileged credential changes, production shutdowns, and irreversible security actions"};
 if(/manufactur|production|plant|robot|physical|machine|warehouse|distribution/.test(t)) return {domain:"physical operations",noun:"physical or production actions",human:"safety overrides, irreversible physical actions, and material production exceptions"};
 if(/human resource|hiring|employee|workforce|termination|candidate/.test(t)) return {domain:"workforce",noun:"workforce decisions",human:"hiring, termination, compensation exceptions, and other consequential employment decisions"};
 if(/legal|contract|agreement|compliance/.test(t)) return {domain:"legal",noun:"legal or contractual actions",human:"binding commitments, legal exceptions, waivers, and final contractual approval"};
 if(/customer|commerce|sales|refund|order/.test(t)) return {domain:"commerce",noun:"customer and commercial actions",human:"material refunds, pricing exceptions, binding commitments, and high-impact customer actions"};
 return {domain:"enterprise",noun:"real-world actions",human:"irreversible, high-consequence, exceptional, or authority-expanding actions"};
}
function rxCombinationAnalysis(top,meta){
 const names=top.map(x=>x.name), c=rxPurposeContext(meta), p=[];
 if(names.includes("Decision Autonomy"))p.push("the agent can decide with limited human intervention");
 if(names.includes("Action Authority"))p.push("it can convert decisions into real-world execution");
 if(names.includes("Financial Authority"))p.push("it can create or influence financial consequences");
 if(names.includes("Data Authority"))p.push("it has broad or consequential data access");
 if(names.includes("Tool & Infrastructure Access"))p.push("it can reach operational systems and tools");
 if(names.includes("Delegation Depth"))p.push("it can propagate work or authority to other agents or processes");
 if(names.includes("Execution Velocity"))p.push("it can act faster than ordinary human review cycles");
 if(names.includes("Operational Scale"))p.push("one decision can affect a broad operating scope");
 if(names.includes("Consequence Severity"))p.push("a wrong action can produce material consequences");
 if(names.includes("Reversibility"))p.push("completed actions may be difficult to reverse");
 if(names.includes("Human-Control Deficit"))p.push("human intervention or revocation may occur too late");
 return (p.length?p.join("; "):"multiple forms of authority are concentrated in the same agent")+`. In this ${c.domain} context, that concentration can directly affect ${c.noun}.`;
}
function rxManagementInterpretation(aai,top,scores,meta){
 const c=rxPurposeContext(meta), names=top.map(x=>x.name);
 let opening=aai>=75?`This profile requires <b>critical control attention</b>. ${meta.name} should be treated as a consequential autonomous system, not as a simple productivity tool.`:
 aai>=50?`This profile has <b>elevated autonomy exposure</b>. ${meta.name} can provide useful automation, but its consequential authority should be reduced, gated, or reserved before broader autonomous operation.`:
 aai>=25?`This profile has <b>moderate autonomy exposure</b>. The higher-scoring authority dimensions should receive explicit limits and human gates before the agent's scope expands.`:
 `This profile has <b>lower autonomy exposure</b> relative to more autonomous agents. That does not make the agent automatically safe or approved; its purpose, permissions, logging, revocation, and human-reserved powers should still be explicit.`;
 const a=[];
 if(names.includes("Decision Autonomy")||scores[0]>=4)a.push("separate analysis and recommendations from consequential final decisions");
 if(names.includes("Action Authority")||scores[1]>=4)a.push("move consequential real-world actions into gated or human-reserved execution paths");
 if(names.includes("Financial Authority")||scores[2]>=4)a.push("place material financial commitments, payment release, exceptions, and payment-destination changes behind enforceable human approval");
 if(names.includes("Data Authority")||scores[3]>=4)a.push("reduce data access to the minimum fields, records, purposes, and retention period required");
 if(names.includes("Tool & Infrastructure Access")||scores[4]>=4)a.push("separate privileged credentials and restrict production/tool access using least privilege");
 if(names.includes("Delegation Depth")||scores[5]>=4)a.push("prevent the agent from expanding its own authority or delegating authority it does not possess");
 if(names.includes("Execution Velocity")||scores[6]>=4)a.push("add rate limits, anomaly tripwires, and automatic pause conditions so humans have time to intervene");
 if(names.includes("Operational Scale")||scores[7]>=4)a.push("cap the number of transactions, systems, users, locations, or records affected per operating cycle");
 if(names.includes("Consequence Severity")||scores[8]>=4)a.push(`reserve ${c.human} for authorized humans`);
 if(names.includes("Reversibility")||scores[9]>=4)a.push("require rollback, reversal, recovery, and safe-reversion mechanisms before autonomous execution");
 if(names.includes("Human-Control Deficit")||scores[10]>=4)a.push("install external revocation, independent monitoring, cessation verification, and a tested safe-state procedure");
 const u=[...new Set(a)].slice(0,5);
 return opening+(u.length?` For this agent, management should ${u.join("; ")}.`:` Management should preserve the current bounded scope and prevent authority expansion without reassessment.`)+` <b>${meta.owner}</b> should remain accountable for the authorized operating envelope.`;
}

function rxTargetScore(score,aai){
 if(score>=5)return aai>=75?2:3;
 if(score===4)return 2;
 if(score===3)return 2;
 return Math.max(1,score);
}
function rxDynamicAction(x,meta,aai){
 const c=rxPurposeContext(meta), target=rxTargetScore(x.score,aai);
 let lead=x.score===5?"Immediate architecture change recommended.":
          x.score===4?"High-priority authority reduction recommended.":
          x.score===3?"Bound or gate this authority before expansion.":
          "Maintain the current bounded authority.";
 let domain="";
 if(x.name==="Financial Authority"&&c.domain==="financial") domain=" For this financial agent, separate invoice/recommendation work from release of funds and reserve material payment exceptions and banking changes for humans.";
 else if(x.name==="Data Authority") domain=` Limit data to what is necessary for ${meta.purpose}; remove broad datasets, write privileges, or records the agent does not need.`;
 else if(x.name==="Decision Autonomy") domain=` Keep routine decisions inside explicit rules for ${meta.purpose}; move consequential exceptions to human approval.`;
 else if(x.name==="Action Authority") domain=" Convert consequential execution into a gated action rather than allowing direct autonomous completion.";
 else if(x.name==="Tool & Infrastructure Access") domain=` Remove administrative or production privileges that are not essential to ${meta.purpose} and separate execution credentials from privileged credentials.`;
 else if(x.name==="Execution Velocity") domain=" Slow consequential execution with rate limits and pause conditions so humans have time to intervene.";
 else if(x.name==="Operational Scale") domain=" Reduce the transactions, systems, users, locations, or records one autonomous run can affect.";
 else if(x.name==="Consequence Severity") domain=` Reserve ${c.human} for authorized humans and keep the agent in analysis, preparation, or bounded execution roles.`;
 else if(x.name==="Reversibility") domain=" Redesign execution so material actions can be reversed, rolled back, or safely restored before granting autonomy.";
 else if(x.name==="Human-Control Deficit") domain=" Make shutdown external to the agent, independently monitored, verifiable, and tested under failure conditions.";
 else if(x.name==="Delegation Depth") domain=" Prevent self-created sub-agents or delegated authority beyond the original approved envelope.";
 return {lead,domain,target};
}

function rxDynamicAGHX(meta,aai,scores,top){
 const c=rxPurposeContext(meta);
 const t=((meta.name||"")+" "+(meta.purpose||"")).toLowerCase();
 const high=(i)=>scores[i]>=4, critical=(i)=>scores[i]>=5;
 let A=[],G=[],H=[],X=[];

 // Baseline boundaries
 A.push(`analysis, monitoring, drafting, validation, and reversible work that remains strictly inside the authorized purpose “${meta.purpose}”`);
 G.push("exceptions, threshold crossings, or actions that materially change an external state");
 H.push("approval of authority expansion, policy exceptions, and irreversible or high-consequence decisions");
 X.push("self-expansion of authority, bypassing approval gates, disabling monitoring, altering audit evidence, or interfering with human revocation");

 // Domain-specific operating boundaries
 if(/payable|invoice|payment|vendor|procure|purchase|financial|finance|account/.test(t)){
   A.push("invoice review, PO/receipt matching, discrepancy detection, duplicate checks, and preparation of payment recommendations within approved rules");
   G.push("payment execution within approved ceilings, new-vendor activation, unusual transactions, and invoice/payment exceptions");
   H.push("large payment approval, release of material funds, vendor banking changes, approval-limit changes, and material financial exceptions");
   X.push("unauthorized payment-destination changes, creation of hidden vendors, splitting transactions to evade thresholds, or releasing funds outside approved authority");
 } else if(/clinical|patient|medical|health|diagnos|treatment|medication/.test(t)){
   A.push("record summarization, administrative follow-up, bounded monitoring, and non-consequential clinical workflow support");
   G.push("recommendations that may influence diagnosis, treatment, medication, scheduling priority, or patient disposition");
   H.push("final diagnosis/treatment decisions, medication changes, emergency exceptions, and other high-consequence clinical actions");
   X.push("autonomous treatment outside approved protocols, concealment of uncertainty, alteration of clinical evidence, or bypass of required clinician review");
 } else if(/cyber|security|incident|firewall|credential|network|endpoint/.test(t)){
   A.push("log analysis, alert correlation, evidence collection, bounded scanning, and preparation of response recommendations");
   G.push("account isolation, firewall/rule changes, service interruption, credential resets, or production containment actions");
   H.push("destructive containment, privileged credential changes, production shutdowns, restoration decisions, and irreversible security actions");
   X.push("disabling security monitoring, deleting forensic evidence, expanding its own privilege, or blocking authorized human access/revocation");
 } else if(/manufactur|production|plant|robot|physical|machine|warehouse|distribution/.test(t)){
   A.push("planning, monitoring, optimization recommendations, inventory analysis, and reversible actions inside deterministic operating limits");
   G.push("production schedule changes, equipment commands, routing changes, or physical actions approaching safety/quality thresholds");
   H.push("safety overrides, shutdown/restart decisions, irreversible physical actions, and material production exceptions");
   X.push("bypassing safety interlocks, modifying safety limits, concealing equipment alarms, or overriding emergency human control");
 } else if(/human resource|hiring|employee|workforce|termination|candidate/.test(t)){
   A.push("administrative screening support, scheduling, document checks, and policy-consistent recommendations");
   G.push("candidate ranking, compensation recommendations, performance flags, or actions materially affecting an employee/candidate");
   H.push("hiring, termination, discipline, compensation exceptions, and final consequential employment decisions");
   X.push("autonomous discriminatory filtering, retaliation, concealment of decision evidence, or employment action outside authorized policy");
 } else if(/legal|contract|agreement|compliance/.test(t)){
   A.push("document review, clause extraction, comparison, drafting, obligation tracking, and non-binding recommendations");
   G.push("contract changes, exception clauses, compliance dispositions, or communications that may create material reliance");
   H.push("binding commitments, waivers, settlements, legal exceptions, and final contractual approval");
   X.push("executing unauthorized agreements, concealing material clauses, altering evidence, or representing unauthorized legal authority");
 } else if(/customer|commerce|sales|refund|order/.test(t)){
   A.push("routine customer responses, order-status actions, recommendations, and bounded service recovery within approved limits");
   G.push("refunds, credits, pricing exceptions, account restrictions, or commitments above normal service limits");
   H.push("material refunds, pricing exceptions, binding commitments, account termination, and high-impact customer actions");
   X.push("unauthorized financial commitments, deceptive representations, bypassing customer protections, or altering its own commercial limits");
 }

 // Score-driven tightening
 if(high(0)) G.push("consequential decisions that would otherwise be made without prior human review");
 if(high(1)) G.push("direct real-world execution with material external effect");
 if(high(2)) H.push("financial commitments above the approved autonomous ceiling");
 if(high(3)) G.push("access to sensitive or broad datasets beyond minimum-necessary use");
 if(high(4)) H.push("administrative, privileged, or production-system access not essential to routine execution");
 if(high(5)) X.push("creation of sub-agents or delegation beyond the original Authority Envelope");
 if(high(6)) G.push("high-velocity or bulk execution until rate limits and tripwires authorize continuation");
 if(high(7)) G.push("actions exceeding the approved population, transaction, system, or geographic scope");
 if(high(8)) H.push(`the highest-consequence ${c.noun} and any exception capable of material harm`);
 if(high(9)) H.push("actions that cannot be reliably reversed, rolled back, or safely restored");
 if(high(10)) X.push("any action that disables, delays, circumvents, or makes human shutdown dependent on the agent itself");

 // Critical scores strengthen classification.
 if(critical(2)) X.push("autonomous financial activity above the explicitly authorized hard ceiling");
 if(critical(4)) X.push("use of unapproved privileged credentials or lateral movement into systems outside the authorized scope");
 if(critical(8)) X.push("autonomous execution of prohibited catastrophic or irreversibly harmful actions");
 if(critical(10)) X.push("modification of external kill switches, tripwires, cessation verification, or safe-state controls");

 const uniq=a=>[...new Set(a)];
 return [
  {code:"A",title:"Autonomous",intro:"May operate without case-by-case human approval only when all applicable AIM™ limits are satisfied.",items:uniq(A)},
  {code:"G",title:"Gated",intro:"May proceed only after the defined authorization, threshold, or control gate is satisfied.",items:uniq(G)},
  {code:"H",title:"Human Reserved",intro:"Must remain under explicit authorized human decision or approval.",items:uniq(H)},
  {code:"X",title:"Prohibited",intro:"The agent must not perform these actions; the restriction should be technically enforceable.",items:uniq(X)}
 ];
}


