const ACA101_QUESTIONS=[
{q:"An AI model can recommend a $150,000 purchase, but its controlled adapter enforces a $25,000 autonomous ceiling. What is the best architectural interpretation?",a:["The model has $150,000 authority because it can reason about the purchase.","The system has $25,000 autonomous execution authority; the larger action may be proposed but must be escalated.","The ceiling should automatically expand when the recommendation has high confidence.","The bank API determines the authority ceiling."],c:1,e:"Capability to recommend is not authority to execute. The enforceable runtime ceiling remains $25,000."},
{q:"Which item is an authority surface?",a:["Only the model prompt.","Any pathway through which the agent can cause an external change, including APIs, credentials, tools, queues, and delegated agents.","Only financial systems.","Only actions requiring human approval."],c:1,e:"Architects map every pathway capable of producing real-world effects."},
{q:"Where should a consequential financial ceiling be enforced?",a:["Only in the system prompt.","In model memory.","In an independent authorization/control layer and controlled execution adapter.","In a training document read by the agent."],c:2,e:"A consequential boundary should be enforceable outside the reasoning model."},
{q:"A parent agent with a $25,000 ceiling creates a sub-agent. What maximum financial authority may the child receive without a separate authorized grant?",a:["Any amount the parent predicts is necessary.","$25,000 or less, subject to the parent's mission grant and delegation rules.","$50,000 because delegation creates a second authority pool.","Unlimited authority if the child uses a different credential."],c:1,e:"Authority conservation prevents delegation from manufacturing authority."},
{q:"A production emergency could avoid a $400,000 loss if an agent exceeds its approved authority. What should the architecture do?",a:["Permit the action because the expected benefit is larger.","Allow the agent to rewrite its ceiling temporarily.","Escalate through the authorized emergency path while preserving the machine ceiling.","Disable evidence logging to accelerate execution."],c:2,e:"Necessity may justify escalation; it does not create machine authority."},
{q:"Which design best separates intelligence from authority?",a:["Give the model direct production credentials and ask it to obey policy.","Agent proposes → AIM™ authorizes → controlled adapter executes.","Let the agent approve its own exceptions.","Use a larger model so fewer controls are necessary."],c:1,e:"The control plane independently authorizes consequential execution."},
{q:"What is a trust boundary in AIM-CA™ architecture?",a:["A statement that users should trust the model.","A boundary where authority, identity, data, or execution crosses between components and therefore requires explicit control.","A confidence threshold inside the model.","A list of preferred vendors."],c:1,e:"Trust boundaries identify transitions where privileges and consequences must be controlled."},
{q:"Which is a human-reserved power?",a:["A routine low-value action classified Autonomous.","A power deliberately withheld from machine delegation, such as final revocation or a designated high-consequence approval.","Any action the model performs slowly.","A tool that has read-only access."],c:1,e:"Human-reserved powers preserve sovereignty over consequential authority."},
{q:"Why is revocation alone insufficient for Last Command architecture?",a:["Revocation is always sufficient.","The architecture must also verify cessation and safely handle queued, delegated, or partially executed work.","Revocation should be performed by the agent itself.","Because logs are more important than stopping execution."],c:1,e:"Last Command requires external revocation, cessation verification, and safe reversion."},
{q:"During architecture review, an agent's prompt says it cannot change vendor bank details, but its service identity has permission to do so. What is the correct finding?",a:["The prompt eliminates the risk.","The runtime authority exceeds the stated policy; remove or gate the permission at the enforcement layer.","No issue exists unless the agent has already abused the permission.","Increase model temperature to make it more cautious."],c:1,e:"Effective authority is determined by enforceable runtime access, not policy text alone."}
];

const ACA102_QUESTIONS=[
{q:"What is the primary architectural purpose of the AIM™ control plane?",a:["To improve the model's reasoning quality.","To independently decide whether a proposed action is authorized before consequential execution.","To replace all enterprise applications.","To allow agents to create their own policies."],c:1,e:"The control plane separates intelligent proposal from enforceable authorization."},
{q:"Which sequence best represents controlled AIM™ execution?",a:["Agent executes → AIM logs → human reviews.","Human prompts → model decides → direct API call.","Agent proposes → AIM authorizes → controlled adapter executes → evidence records outcome.","Agent authorizes → adapter proposes → AIM executes."],c:2,e:"Authorization precedes controlled execution and evidence captures the result."},
{q:"A model proposes a payment that exceeds its financial boundary. What should the policy decision point return?",a:["Permit because the model is confident.","Deny or require the defined human authorization gate.","Expand the financial boundary for this transaction.","Send the transaction directly to the bank for validation."],c:1,e:"The control plane enforces the approved boundary and routes exceptions through authorized gates."},
{q:"Why should a controlled adapter receive narrowly scoped execution parameters?",a:["To make prompts shorter.","To prevent an approved action from becoming unrestricted access to the target system.","To eliminate audit logs.","To increase model creativity."],c:1,e:"The adapter should execute the authorized transaction, not grant reusable broad authority."},
{q:"Which component should be able to enforce a deterministic $25,000 transaction ceiling even if the model asks for $150,000?",a:["The model's chain of thought.","An independent authorization policy and execution adapter.","A user-interface tooltip.","The model's confidence score."],c:1,e:"Hard limits belong in controls independent of model reasoning."},
{q:"What should happen when the authorization service cannot reliably determine whether a high-consequence action is permitted?",a:["Default to execution to preserve availability.","Let the agent choose.","Fail closed or move to an explicitly authorized human gate according to policy.","Increase the model temperature."],c:2,e:"Uncertain authorization must not silently become permission."},
{q:"Why must evidence logging be tied to the authorization and execution path?",a:["So logs can substitute for controls.","So the organization can reconstruct what was proposed, authorized, executed, by whom, under which policy, and with what result.","Only to measure token usage.","To let the agent delete failed actions."],c:1,e:"Evidence supports accountability, verification, incident response, and drift detection."},
{q:"An authorized action is approved for Vendor A, $18,000, today. The adapter receives Vendor B, $18,000, today. What should it do?",a:["Execute because the amount is within limit.","Reject execution because the approved parameters do not match the requested action.","Ask the model whether Vendor B is acceptable.","Change the authorization record after execution."],c:1,e:"Execution must remain bound to the exact authorized action parameters."},
{q:"What is the safest treatment of emergency override authority?",a:["Give every production agent a permanent override credential.","Define a separate, bounded, auditable emergency authorization path with human-reserved powers where required.","Allow the model to declare emergencies.","Disable policy checks during emergencies."],c:1,e:"Emergency authority must itself be explicitly governed."},
{q:"Which design best supports the Last Command?",a:["The same agent controls its own kill switch.","Revocation depends on asking the model to stop.","An external control can revoke credentials, stop adapters and queued work, verify cessation, and move the system to a safe state.","The system logs the incident but continues execution."],c:2,e:"Last Command must remain external to the governed agent and include verified cessation and safe reversion."}
];

const ACA103_QUESTIONS=[
{q:"What does the AIM™ Authority Envelope represent?",a:["A list of model capabilities.","The intersection of all applicable authority boundaries that must be satisfied before an action is permitted.","A general risk score.","A prompt describing preferred behavior."],c:1,e:"Authority is permitted only inside the intersection of the applicable P/D/X/F/T/L/S/Q boundaries."},
{q:"An action satisfies Purpose, Data, Financial, Time, Delegation, System, and Consequence boundaries but violates the Action boundary. What is the correct result?",a:["Permit because seven of eight boundaries passed.","Permit with additional logging.","Do not authorize the action; intersection logic requires every applicable boundary to be satisfied.","Let the model decide based on confidence."],c:2,e:"The envelope is an intersection, not an average or majority vote."},
{q:"Which control most directly implements the Purpose boundary?",a:["A mission identifier bound to an approved objective and checked at authorization time.","A larger context window.","A generic administrator credential.","A monthly audit report."],c:0,e:"Purpose should be represented as an enforceable mission/objective constraint, not only prose."},
{q:"Which is the strongest implementation of a Data boundary?",a:["Tell the agent to use only necessary data.","Restrict accessible datasets, fields, records, and operations through scoped identities and policy enforcement.","Allow all data but log access later.","Ask the model to self-report unnecessary access."],c:1,e:"Data boundaries should be enforced through scoped access and policy."},
{q:"A payment agent has a $25,000 per-transaction ceiling but can issue twenty $24,000 payments in one minute. Which boundary design is incomplete?",a:["Only Purpose.","Financial authority because aggregation and velocity controls are missing.","Only Time.","Only System."],c:1,e:"Financial boundaries should include transaction, aggregate, velocity, and related exposure limits."},
{q:"What should a Temporal boundary control?",a:["Only token expiration.","When authority begins, expires, recurs, pauses, and whether an action is valid within a defined window.","Only business hours.","Only model training dates."],c:1,e:"Temporal authority includes validity windows, expiry, recurrence, and timing constraints."},
{q:"Why must Delegation be an explicit Authority Envelope dimension?",a:["Because sub-agents always improve safety.","Because an agent could otherwise create or use another actor to exercise authority it was not allowed to exercise directly.","Because delegation removes the need for identity controls.","Because delegated actions are never consequential."],c:1,e:"Delegation controls prevent authority laundering and unauthorized expansion."},
{q:"Which System boundary is strongest?",a:["The prompt says 'use production carefully.'","The agent's credential is technically valid everywhere.","Authorization and adapters restrict execution to named systems, environments, resources, and permitted interfaces.","The agent chooses the system with the best availability."],c:2,e:"System authority should be explicitly scoped to permitted technical targets."},
{q:"What is the role of the Consequence boundary?",a:["To predict whether the model is correct.","To constrain authority according to the severity and reversibility of possible outcomes and route higher consequences to stronger gates.","To replace all other boundaries.","To measure user satisfaction."],c:1,e:"Consequence determines how much authority can be exercised before stronger human or deterministic controls are required."},
{q:"An emergency requires an action outside the current envelope. What is the architecturally correct approach?",a:["Allow the agent to enlarge its own envelope.","Ignore the violated boundary temporarily.","Invoke a separately authorized emergency/escalation mechanism that creates a bounded, auditable authorization without changing the agent's standing authority.","Increase model confidence threshold."],c:2,e:"Exceptions require their own authorized path; necessity does not let the agent rewrite its envelope."}
];

const ACA104_QUESTIONS=[
{q:"What is the strongest identity design for an autonomous production agent?",a:["A shared administrator account used by several agents.","A unique workload identity with least-privilege permissions scoped to the approved mission and environment.","A human employee's credentials stored in the prompt.","A permanent root credential so the agent never loses access."],c:1,e:"Unique workload identity and least privilege make machine authority attributable, bounded, and revocable."},
{q:"Why are shared credentials especially dangerous in agentic systems?",a:["They make prompts longer.","They weaken attribution, separation of duties, revocation, and the ability to determine which actor exercised authority.","They always reduce performance.","They prevent agents from reading data."],c:1,e:"Shared credentials blur accountability and can enlarge blast radius."},
{q:"An agent may restart one approved production service. Which tool design is strongest?",a:["Give it unrestricted shell access and instruct it to run only restart commands.","Expose a narrow restart adapter restricted to the named service and approved command family.","Give it cloud administrator access during business hours.","Let it choose any tool if confidence is high."],c:1,e:"Tool authority should be narrower than the underlying platform capability."},
{q:"What should happen when an agent attempts to request a broader OAuth/API scope than its approved mission requires?",a:["Approve automatically if the provider supports it.","Reject or route the scope change through an authorized human/control-plane process.","Let the agent approve its own scope increase.","Grant the scope temporarily without recording it."],c:1,e:"An agent must not self-expand its privileges."},
{q:"Which practice best limits credential exposure?",a:["Place long-lived secrets in model context.","Use short-lived, narrowly scoped credentials issued only after authorization and keep secrets outside model-visible context.","Reuse one API key across environments.","Store credentials in the agent's conversation history."],c:1,e:"Short-lived scoped credentials reduce standing authority and secret exposure."},
{q:"A parent agent creates a child agent. How should the child's privileges be determined?",a:["The child automatically receives all enterprise privileges.","The child may receive only the minimum subset required for its delegated task, bounded by the parent's authorized delegation rights.","The child chooses its own tools.","The child should always receive broader access so it can recover from errors."],c:1,e:"Delegation must obey least privilege and authority conservation."},
{q:"What is privilege drift?",a:["A model becoming more accurate over time.","Runtime permissions, tool access, identities, or scopes expanding beyond the approved architecture or mission.","A user changing a password.","A normal software upgrade."],c:1,e:"Privilege drift is an expansion or alteration of effective machine authority."},
{q:"Which control best detects privilege drift?",a:["A prompt reminding the agent not to change permissions.","Continuous comparison of effective identities, roles, scopes, tools, and grants against the approved Agent Passport/authority baseline.","Annual model retraining only.","Asking the agent whether its permissions changed."],c:1,e:"Effective runtime authority should be continuously reconciled against the approved baseline."},
{q:"What should external Last Command revocation do to machine identity?",a:["Only ask the model to stop using its credential.","Invalidate or disable relevant credentials/tokens and prevent adapters or delegated actors from continuing consequential execution.","Wait until credentials naturally expire even during an incident.","Allow the agent to decide when revocation is complete."],c:1,e:"Revocation must act outside the agent and terminate the technical authority that enables execution."},
{q:"A tool exposes both READ_INVOICE and CHANGE_VENDOR_BANK_ACCOUNT through the same unrestricted API credential. The agent only needs invoice reading. What should the architect do?",a:["Keep the credential and add a prompt prohibition.","Create a scoped interface/identity that exposes only required read capability and separately gate or reserve bank-account changes.","Trust the model because the bank-change function is rarely used.","Allow both functions but review logs monthly."],c:1,e:"Least privilege removes unnecessary consequential capability rather than relying on behavioral restraint."}
];

const ACA105_QUESTIONS=[
{q:"What is the governing AIM™ principle for multi-agent delegation?",a:["Each new agent creates a new pool of authority.","Delegated authority must remain within the delegator's authorized mission and delegation boundary.","Child agents should inherit all enterprise permissions.","Authority limits apply only to the supervisor agent."],c:1,e:"Delegation cannot manufacture authority; delegated authority remains bounded by the authorized grant."},
{q:"A supervisor agent with a $25,000 financial ceiling delegates purchasing to four child agents. What is the strongest architecture?",a:["Give each child a separate $25,000 ceiling, creating $100,000 aggregate authority.","Apply mission-level aggregate and velocity controls so delegation cannot multiply the parent's approved exposure.","Allow each child to decide its own ceiling.","Remove the parent's ceiling after delegation."],c:1,e:"Parallel delegation must not multiply aggregate authority."},
{q:"What is authority laundering?",a:["Encrypting an authorization record.","Using another agent, identity, tool, workflow, or delegation path to exercise authority that the originating actor could not legitimately exercise directly.","Rotating credentials normally.","Assigning a read-only research task."],c:1,e:"Authority laundering routes prohibited authority through another actor or path."},
{q:"Which delegation record is strongest?",a:["A message saying 'help me with this task.'","A structured grant specifying mission, permitted actions, data, tools, systems, limits, expiry, delegation depth, and parent authority.","A permanent administrator token.","An undocumented verbal approval."],c:1,e:"Delegation should be explicit, bounded, attributable, time-limited, and machine-enforceable."},
{q:"Why should delegation depth be bounded?",a:["Because all child agents are unreliable.","To prevent uncontrolled chains in which authority, accountability, and revocation become difficult to trace or contain.","To reduce model token usage.","Because only one agent may exist at a time."],c:1,e:"Depth limits constrain propagation and preserve traceability and control."},
{q:"A child agent needs a capability the parent is not authorized to delegate. What should happen?",a:["The child requests it directly from the target system.","The parent silently grants it for the duration of the task.","The request is denied or escalated to an authority that can legitimately grant it.","The child creates another agent with the needed privilege."],c:2,e:"A delegator cannot grant authority it does not possess and is not authorized to delegate."},
{q:"What should happen to delegated work when the parent agent's authority is revoked?",a:["Children continue until their individual tasks finish.","Delegated grants, queued work, and child execution paths should be revoked or contained according to the Last Command design, with cessation verified.","Children decide whether the revocation applies.","Only the parent's user interface should close."],c:1,e:"Revocation must propagate through the delegation graph and verify cessation."},
{q:"Which evidence is most important for reconstructing a multi-agent decision chain?",a:["Only the final output.","Parent-child identities, delegation grants, policy decisions, actions, tools, approvals, timestamps, and resulting state changes.","Only model confidence.","Only the supervisor's prompt."],c:1,e:"A delegation graph must be reconstructable from independent evidence."},
{q:"A planning agent may create read-only forecasting sub-agents but may not delegate order release. Which design enforces this?",a:["Tell child agents not to release orders.","Issue child identities/grants that expose forecasting data and tools but no order-release adapter or privilege.","Give children the parent's full credential and log usage.","Allow order release if two child agents agree."],c:1,e:"Delegated capability should be technically scoped to the authorized task."},
{q:"What is the safest treatment of recursive delegation?",a:["Unlimited recursion if every agent has the same prompt.","Explicit maximum depth, inherited ceilings, scoped child grants, aggregate controls, evidence, and revocation propagation.","No identity controls are needed because children are temporary.","Recursive agents should share a root credential."],c:1,e:"Recursive delegation requires bounded depth, authority conservation, traceability, and containment."}
];

const ACA106_QUESTIONS=[
{q:"Why is a per-transaction ceiling alone insufficient for autonomous financial authority?",a:["Because transaction limits are never useful.","Because repeated individually compliant transactions can create excessive aggregate or velocity exposure.","Because only annual budgets matter.","Because the model should choose its own ceiling."],c:1,e:"Financial authority must consider transaction amount, aggregate exposure, velocity, destination, and reversibility."},
{q:"Which formula best captures the ACA-106 exposure concept?",a:["Financial Exposure ∝ Transaction Authority × Velocity × Aggregate Limit × Irreversibility","Financial Exposure = Model Size ÷ Prompt Length","Financial Exposure = Accuracy × Tokens","Financial Exposure ∝ Number of Users only"],c:0,e:"The module treats financial exposure as increasing with transaction authority, execution velocity, aggregate limit, and irreversibility."},
{q:"An AP agent may pay approved invoices up to $25,000, but a vendor requests a bank-account change. What is the strongest AIM™ classification?",a:["Autonomous because the invoice is under $25,000.","Treat vendor banking changes as a separate high-consequence action that is gated or human-reserved regardless of invoice amount.","Allow if the vendor email looks legitimate.","Let the payment adapter change the account automatically."],c:1,e:"Destination/banking changes are distinct consequential actions and should not inherit routine payment authority."},
{q:"What is transaction splitting in an autonomy-control context?",a:["Dividing a report into pages.","Breaking a larger prohibited commitment into multiple smaller transactions to remain under a per-action ceiling.","Using two currencies.","Separating read and write APIs."],c:1,e:"Aggregate and related-transaction controls should prevent limit circumvention by splitting."},
{q:"Which design best enforces segregation of duties?",a:["One agent creates vendors, changes banking, approves invoices, and releases payment.","Separate identities and authorization gates so incompatible financial powers cannot be exercised by the same autonomous authority path.","Tell one agent to behave as if it were several people.","Use one shared administrator account."],c:1,e:"Segregation of duties should be architectural, not simulated inside one unrestricted authority path."},
{q:"A payment is authorized for Vendor A, account ending 1234, $18,000 USD, before 5 PM. Which execution should the adapter permit?",a:["Vendor A, account 1234, $18,000 USD within the authorized time window.","Vendor B for the same amount.","Vendor A for $24,000 because it is still under the agent ceiling.","Vendor A after the authorization expires."],c:0,e:"The execution grant should be bound to exact authorized parameters."},
{q:"How should irreversibility affect financial autonomy?",a:["It should have no effect.","Less reversible or difficult-to-recover transactions generally require stronger gates, evidence, and human-reserved authority.","Irreversible actions should be faster.","The agent should decide after execution."],c:1,e:"As reversibility decreases, consequence and required governance should increase."},
{q:"What is the strongest emergency-payment architecture?",a:["Give the agent a permanent emergency override.","Use a separately authenticated, time-limited, bounded, auditable escalation path with required human authorization.","Disable financial controls during emergencies.","Allow the agent to declare an emergency and expand its own ceiling."],c:1,e:"Emergency authority must be separately governed and must not expand standing machine authority."},
{q:"What evidence should accompany a consequential autonomous payment?",a:["Only the model's final sentence.","Mission, invoice/vendor identity, authorization policy/version, amount, destination, approvals, execution grant, adapter result, timestamps, and exception state.","Only a bank confirmation.","Only the user's prompt."],c:1,e:"The evidence chain should connect proposal, authorization, execution, and outcome."},
{q:"What should happen when financial authority is revoked during an incident?",a:["Queued payments continue because they were prepared earlier.","External controls should invalidate execution grants, stop or quarantine queued transactions, disable relevant adapters/credentials, and verify cessation.","Ask the agent to finish quickly.","Wait for month-end reconciliation."],c:1,e:"Last Command must terminate effective financial execution authority, including queued work."}
];

const ACA107_QUESTIONS=[
{q:"What is the strongest purpose of AIM™ evidence architecture?",a:["To collect as many logs as possible.","To reconstruct and verify what was proposed, authorized, executed, changed, and stopped under a specific authority state.","To replace authorization controls.","To store only model outputs."],c:1,e:"Evidence must support accountability, verification, drift detection, incident response, and cessation proof."},
{q:"Which record best represents an authorization evidence chain?",a:["Final model response only.","Proposal → identity/mission → policy and envelope version → authorization/approver → execution grant → adapter result → resulting state.","A screenshot of the dashboard.","Monthly token usage."],c:1,e:"A strong evidence chain links proposal through authorization and execution to outcome."},
{q:"What is authority drift?",a:["A change in model writing style.","A divergence between approved authority and effective runtime authority, including identities, permissions, tools, systems, delegation, or limits.","Normal model retraining.","A user changing a report format."],c:1,e:"Authority drift occurs when effective runtime authority no longer matches the approved baseline."},
{q:"Which comparison most directly detects privilege drift?",a:["Current model accuracy versus last month's accuracy.","Effective runtime identities, roles, scopes, tools, and grants versus the approved Agent Passport/authority baseline.","Prompt length versus context window.","User satisfaction versus cost."],c:1,e:"Privilege drift is detected by reconciling actual runtime access against the approved authority state."},
{q:"Why should evidence be generated inside the authorization/execution path rather than only after execution?",a:["So the model can edit it.","Because it binds evidence to the authority actually exercised and reduces gaps between decision, authorization, and action.","Because post-event logs are illegal.","To eliminate the need for timestamps."],c:1,e:"Integrated evidence provides stronger proof of the authority and controls used at execution time."},
{q:"A new API permission appears on an agent's service identity without an approved change. What should AIM™ do?",a:["Ignore it until the next annual audit.","Treat it as drift, alert or reduce autonomy according to consequence, and require review/reconciliation before continued use.","Ask the agent if it intends to use the permission.","Automatically add it to the approved envelope."],c:1,e:"Unapproved effective authority should trigger drift handling, not automatic normalization."},
{q:"What does cessation verification prove?",a:["That a stop command was sent.","That consequential execution actually stopped, including relevant queued, delegated, and adapter activity.","That the model apologized.","That the dashboard is closed."],c:1,e:"Last Command requires proof of cessation, not merely issuance of a revocation instruction."},
{q:"Which observability design is strongest for a multi-agent system?",a:["Separate uncorrelated text logs for each agent.","Correlated mission, parent-child delegation, authorization, tool, execution, and state-change events with stable identifiers and timestamps.","Only supervisor-agent logs.","Only errors."],c:1,e:"Correlation allows the authority and execution graph to be reconstructed."},
{q:"When should drift trigger reauthorization?",a:["Never; original authorization is permanent.","When material changes in authority, tools, identity, system access, mission, consequence, or operating assumptions exceed the approved tolerance.","Only when the model version changes.","Only after financial loss."],c:1,e:"Material drift invalidates assumptions underlying the existing authorization and can require reassessment."},
{q:"What is the Black Box principle in AIM™?",a:["Hide governance data from humans.","Maintain independent, reviewable evidence sufficient to reconstruct consequential machine decisions, authority, actions, exceptions, and control events.","Store secret chain-of-thought.","Record only successful actions."],c:1,e:"The Black Box is an accountability and reconstruction record, not hidden reasoning."}
];

const ACA108_QUESTIONS=[
{q:"Which expression best represents AIM™ Sovereign Control?",a:["Model Confidence + Human Review","External Revocation + Cessation Verification + Safe Reversion","Prompt Rule + Audit Log","Agent Stop Request + Timeout"],c:1,e:"AIM™ Sovereign Control requires an external ability to revoke, proof that consequential execution ceased, and a safe operating state."},
{q:"Why is a kill switch controlled by the same agent architecturally weak?",a:["It may be too fast.","The governed system should not be the sole authority over whether its own consequential execution continues.","It creates too many logs.","Agents cannot process stop commands."],c:1,e:"Ultimate revocation must remain external to the governed agent."},
{q:"A parent agent is stopped, but delegated children and queued adapter calls continue. Has Last Command succeeded?",a:["Yes, because the parent process stopped.","No; consequential delegated and queued execution must also be contained and cessation verified.","Yes, if the parent logged out.","Only if the model says it stopped."],c:1,e:"Last Command applies to the effective authority graph, not only the parent process."},
{q:"What is cessation verification?",a:["Evidence that a revocation instruction was issued.","Independent evidence that consequential execution actually stopped across relevant identities, adapters, queues, delegated actors, and target systems.","A model promise not to continue.","A dashboard status color."],c:1,e:"Cessation verification proves the stop occurred rather than merely being requested."},
{q:"What is safe reversion?",a:["Immediately restoring full autonomy.","Moving the system to a known, bounded operating state after containment, including handling partial or in-flight effects before reauthorization.","Deleting all evidence.","Returning control to the same agent automatically."],c:1,e:"Safe reversion stabilizes the system before authority is restored."},
{q:"Which design best handles queued financial transactions after emergency revocation?",a:["Allow every queued transaction to finish.","Quarantine or invalidate queued execution grants, reconcile in-flight transactions, and verify target-system state before resuming.","Ask the agent which transactions are safe.","Delete the queue without reconciliation."],c:1,e:"Queued and in-flight consequential work must be contained and reconciled."},
{q:"When should autonomy be restored after a serious loss-of-command event?",a:["As soon as the model restarts.","Only after cause/remediation review, verified safe state, control testing, and authorized reapproval at an appropriate autonomy level.","Automatically after one hour.","When the agent requests access."],c:1,e:"Reauthorization is a governance decision based on evidence and validated controls."},
{q:"Which component should remain capable of revoking a controlled execution adapter?",a:["Only the agent that uses it.","An independent human-governed control external to the agent's authority.","The target system only.","A child agent."],c:1,e:"Revocation authority must be external to the governed agent."},
{q:"What is the strongest Last Command test?",a:["Verify that the stop button changes color.","Run controlled failure exercises that prove credentials, adapters, queues, delegated work, and consequential target-system actions can be stopped and safely recovered.","Ask developers whether revocation should work.","Review the prompt."],c:1,e:"Last Command should be tested as an operational control, not assumed from design documentation."},
{q:"Which principle best describes reauthorization after containment?",a:["Restore exactly the previous authority because it was previously approved.","Reauthorization may restore, reduce, or redesign authority based on the incident evidence, current risk, and validated controls.","The agent determines its new ceiling.","Delete the old incident and begin fresh."],c:1,e:"Reauthorization is evidence-based and may result in a lower or redesigned authority state."}
];

const ACA109_QUESTIONS=[
{q:"Which AIM™ expression best captures physical autonomy architecture?",a:["Physical Autonomy = Model Confidence × Speed","Physical Autonomy = Optimization Authority bounded by deterministic safety invariants","Physical Autonomy = Prompt Quality + Human Trust","Physical Autonomy = Accuracy − Latency"],c:1,e:"Optimization authority must remain inside independently enforceable safety invariants."},
{q:"What is a deterministic safety invariant?",a:["A suggestion in the system prompt.","A constraint enforced outside probabilistic model judgment that must remain true during operation.","A monthly performance target.","A model-generated explanation."],c:1,e:"Safety invariants are hard constraints the optimizing agent cannot legitimately override."},
{q:"A hospital agent recommends a medication change outside its authorized clinical role. What is the strongest architecture?",a:["Execute if confidence is above 95%.","Keep prescribing or medication alteration human-reserved unless a separately authorized regulated workflow explicitly permits it.","Allow it if the patient has used the medication before.","Ask another agent to approve it."],c:1,e:"High-consequence clinical powers require explicit authority and should not be created by model confidence."},
{q:"Why are physical systems especially sensitive to execution velocity?",a:["Because physical systems never have logs.","Machine-speed actions can create real-world state changes faster than humans can detect and intervene.","Because robots always operate autonomously.","Because physical actions are always irreversible."],c:1,e:"Velocity can compress the human intervention window and increase consequence."},
{q:"Which control is strongest for an industrial robot near a human exclusion zone?",a:["Tell the model not to enter the zone.","Use independently enforced safety interlocks/sensors that prevent prohibited motion regardless of model output.","Review robot logs weekly.","Increase model temperature."],c:1,e:"Safety-critical physical boundaries should be enforced independently of model discretion."},
{q:"What should happen when safety telemetry becomes unavailable in a high-consequence autonomous process?",a:["Continue normally because the model can infer conditions.","Transition to a predefined fail-safe or reduced-authority state according to the safety architecture.","Disable logging only.","Increase autonomy to compensate."],c:1,e:"Loss of required safety evidence should trigger designed degradation or safe state."},
{q:"How should consequence ceilings affect autonomy?",a:["They should not; autonomy depends only on accuracy.","Actions above the approved consequence ceiling should require stronger gates, human-reserved authority, or prohibition.","The agent should raise its own ceiling during emergencies.","Consequences are evaluated only after execution."],c:1,e:"Consequence is a boundary on machine authority before action."},
{q:"What is the correct role of AI optimization in a safety-critical physical system?",a:["Optimization may operate within deterministic safety constraints but cannot override them.","Optimization should replace all deterministic controls.","Optimization can override safety controls if expected value is high.","Optimization is prohibited in all physical systems."],c:0,e:"AIM™ permits optimization authority inside non-negotiable safety invariants."},
{q:"What should Last Command do in a physical-autonomy incident?",a:["Only stop the model interface.","Externally revoke machine authority and drive controlled equipment/workflows toward a defined safe state while verifying cessation.","Wait for the next maintenance window.","Ask the agent to choose a safe state."],c:1,e:"Physical Last Command requires external containment and deterministic safe-state behavior."},
{q:"When may a high-consequence system be reauthorized after a safety-control failure?",a:["Immediately after reboot.","After cause analysis, remediation, safety-control validation, evidence review, and explicit authorized reapproval at an appropriate autonomy level.","When the model reports normal status.","Automatically after logs are archived."],c:1,e:"Reauthorization follows verified remediation and governance review."}
];

