let aimCaFinalExamAttempt=null;
function aimCaExamEligible(){return [101,102,103,104,105,106,107,108,109,110].every(n=>localStorage.getItem("aimCaAca"+n+"Badge431")==="1")}
function aimCaShuffle(a){let x=a.slice();for(let i=x.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[x[i],x[j]]=[x[j],x[i]]}return x}
function startAimCaFinalExam(){
 const p=document.getElementById("academyPath");if(!p)return;
 if(!aimCaPrerequisiteMet()){p.innerHTML='<div class="acaResult fail"><h3>AIM-CA™ PREREQUISITE REQUIRED</h3><p>An active AIM-CP™ credential is required in production.</p></div>';return}
 if(!aimCaExamEligible()&&!aimCaTestUnlock()){p.innerHTML='<div class="acaResult fail"><h3>FINAL EXAM LOCKED</h3><p>Pass ACA-101 through ACA-110 first.</p><button class="secondary" onclick="showAimCaPath()">BACK</button></div>';return}
 const selected=aimCaShuffle(AIM_CA_FINAL_EXAM_BANK);
 aimCaFinalExamAttempt={qs:selected,answers:{},started:Date.now()};renderAimCaFinalExam()
}
function renderAimCaFinalExam(){
 const p=document.getElementById("academyPath"),e=aimCaFinalExamAttempt;if(!p||!e)return;
 p.innerHTML=`<div class="pathHeader"><div><span class="academyEyebrow">AIM-CA™ · FINAL CERTIFICATION EXAM</span><h2>Architect Certification Examination</h2><p>50 questions · 5 from each ACA module · 80% (40/50) required.</p></div><button class="secondary" onclick="showAimCaPath()">EXIT EXAM</button></div><div class="acaAssessment"><div class="caPrinciple"><b>Exam Standard</b><br>Apply AIM™ architecture principles and select the strongest governed architecture.</div>${e.qs.map((q,i)=>`<div class="acaQ"><b>${i+1}. ${q.q}</b>${q.a.map((a,j)=>`<label><input type="radio" name="caexam_${i}" value="${j}" onchange="aimCaFinalExamAttempt.answers[${i}]=${j}"><span>${a}</span></label>`).join("")}</div>`).join("")}<button class="primary" onclick="submitAimCaFinalExam()">SUBMIT FINAL EXAM</button><div id="aimCaExamResult"></div></div>`;p.scrollIntoView({behavior:"smooth",block:"start"})
}
function submitAimCaFinalExam(){
 const e=aimCaFinalExamAttempt,r=document.getElementById("aimCaExamResult");if(!e||!r)return;let score=0;e.qs.forEach((q,i)=>{if(Number(e.answers[i])===q.c)score++});const pass=score>=40;
 localStorage.setItem("aimCaFinalExamLast431",JSON.stringify({score,pass,total:50,at:new Date().toISOString()}));if(pass)localStorage.setItem("aimCaFinalExamPassed431","1");
 r.innerHTML=`<div class="acaResult ${pass?"pass":"fail"}"><h3>${score}/50 · ${pass?"PASS":"NOT YET PASSED"}</h3><p>${pass?"AIM-CA™ Final Certification Exam passed. Advanced Simulator, Enterprise Design Practical, and Architecture Defense remain separate certification requirements.":"40/50 is required. Correct answers are not displayed after a failed attempt."}</p><div class="acaResultActions"><button class="secondary" onclick="startAimCaFinalExam()">NEW EXAM ATTEMPT</button><button class="secondary" onclick="showAimCaPath()">BACK TO ARCHITECT PATH</button></div>${pass?'<div class="acaBadge"><b>AIM-CA™</b><span>FINAL CERTIFICATION EXAM</span><strong>EXAM REQUIREMENT PASSED</strong></div>':""}</div>`;r.scrollIntoView({behavior:"smooth",block:"center"})
}

