 let score=0;ACA108_QUESTIONS.forEach((q,i)=>{if(Number(aca108Answers[i])===q.c)score++});
 const pass=score>=8,r=document.getElementById("aca108Result");if(!r)return;
 if(pass)localStorage.setItem("aimCaAca108Badge431","1");
