 let score=0;ACA105_QUESTIONS.forEach((q,i)=>{if(Number(aca105Answers[i])===q.c)score++});
 const pass=score>=8,r=document.getElementById("aca105Result");if(!r)return;
 if(pass)localStorage.setItem("aimCaAca105Badge431","1");
