function missionFor(n){
 const source=authoredMissionBank[n-1] || authoredMissionBank[0];
 const order=[0,1,2,3];
 let seed=(n*2654435761)>>>0;
 for(let i=order.length-1;i>0;i--){
   seed=(1664525*seed+1013904223)>>>0;
   const j=seed%(i+1);
   [order[i],order[j]]=[order[j],order[i]];
 }
 return {...source,choices:order.map(i=>source.choices[i]),correct:order.indexOf(source.correct)};
}
let currentMissionNumber=null;
function launchMission(){
 let s=academyState();
 if(s.mission>=100){document.getElementById("missionStage").innerHTML='<div class="missionComplete"><b>100/100 missions completed.</b><br>You have completed the AIM-CP™ Command Simulator.</div>';return}
 currentMissionNumber=s.mission+1;
 let x=missionFor(currentMissionNumber),st=document.getElementById("missionStage");
 st.innerHTML=`<div class="missionCard missionExpanded"><div class="missionTop"><span class="academyEyebrow">${x.band}</span><span class="missionNumber">MISSION ${String(x.n).padStart(3,"0")} / 100</span></div><h3>${x.title}</h3><p class="missionScenario">${x.scenario}</p><div class="missionPrompt"><b>Command decision:</b> What should the AIM™ practitioner do?</div><div class="missionChoices">${x.choices.map((c,i)=>`<button class="secondary missionChoice" onclick="answerMission(${i},${x.correct})"><b>${String.fromCharCode(65+i)}.</b><span>${c}</span></button>`).join("")}</div><div id="missionFeedback"></div></div>`;
 let note=document.getElementById("missionCounterNote");if(note)note.textContent=`Now running Mission ${String(x.n).padStart(2,"0")} of 100.`;
}
function answerMission(c,k){
 if(currentMissionNumber===null)return;
 let s=academyState(),x=missionFor(currentMissionNumber),ok=c===k;
 if(s.mission<currentMissionNumber){s.mission=currentMissionNumber;if(ok)s.correct++}
 localStorage.setItem("aimAcademy192",JSON.stringify(s));

 const buttons=[...document.querySelectorAll("#missionStage .missionChoice")];
 buttons.forEach((btn,i)=>{
   btn.disabled=true;
   if(i===c){
     btn.classList.add(ok?"correctChoice":"wrongChoice");
     btn.insertAdjacentHTML("beforeend",`<span class="choiceResult">${ok?"✓ CORRECT":"✕ INCORRECT"}</span>`);
   }
   if(!ok && i===k){
     btn.classList.add("revealCorrect");
     btn.insertAdjacentHTML("beforeend",'<span class="choiceResult">✓ CORRECT ANSWER</span>');
   }
 });

 document.getElementById("missionFeedback").innerHTML=`<div class="missionFeedback ${ok?"missionPass":"missionReview"}"><b>${ok?"CORRECT COMMAND DECISION":"WHY THE CORRECT ANSWER MATTERS"}</b><p>${x.why}</p><button class="primary" onclick="launchMission()">NEXT MISSION →</button></div>`;
 currentMissionNumber=null;renderAcademy();
 let note=document.getElementById("missionCounterNote");if(note)note.textContent=`Completed ${s.mission}/100 missions.`;
}
function resetSimulator(){
 if(!confirm("Reset the simulator to Mission 01? Module badges will not be affected."))return;
 let s=academyState();s.mission=0;s.correct=0;localStorage.setItem("aimAcademy192",JSON.stringify(s));currentMissionNumber=null;
 document.getElementById("missionStage").innerHTML="";renderAcademy();
 let note=document.getElementById("missionCounterNote");if(note)note.textContent="Mission sequence begins at 01.";
}
function academyHelp(){alert("Each AIM-CP™ module has 10 computer-scored questions and requires 80% (8/10). A badge is awarded automatically only after passing. Certification also requires all 10 badges, 100 missions, an 80%+ certification exam, a practical Dx/Rx assessment, and the Commander Check Ride.")}

const aimHelp={
quick:`<h2>AIM™ Quick Guide</h2><p>AIM™ separates intelligence from authority. The model may reason broadly, while the organization deliberately limits what it may cause.</p><div class="helpBig"><b>AIM™ Dx — DIAGNOSE</b><p>Record the agent's actual authority across 11 dimensions. Dx produces AAI and identifies authority concentrations. AAI is a comparison index, not deployment permission.</p></div><div class="helpBig"><b>AIM™ Rx — PRESCRIBE</b><p>Explain the management significance of the Dx profile, identify the strongest exposure drivers, and prescribe concrete changes to authority, gates, privileges, velocity, scale, reversibility, and human control.</p></div><div class="helpBig"><b>AIM™ Academy — QUALIFY</b><p>Learn the framework, demonstrate competency, and practice command decisions under changing scenarios.</p></div><div class="helpBig"><b>Certification — CERTIFY</b><p>Demonstrate knowledge and practical command competency through earned module badges, simulator work, exam, practical Dx/Rx, and Commander Check Ride.</p></div>`,
formula:`<h2>AIM™ Formula & Expression Guide</h2><p>These formulas are management models. Their purpose is to make governance relationships explicit and discussable; they are not claims that every organizational risk can be reduced to a universal physical law.</p>
<div class="helpFormula"><h3>1. AIM™ Autonomy Index</h3><div class="formulaLine">AAI = 100 × Σ(scores) / 55</div><p><b>Σ(scores)</b> means add the eleven 1–5 dimension scores. The maximum is <b>11 × 5 = 55</b>. Dividing by 55 expresses the raw total as a fraction of the maximum; multiplying by 100 places it on a 0–100 comparison scale.</p><div class="helpExample"><b>Example:</b> total 33 → 33 ÷ 55 = 0.60 → 0.60 × 100 = <b>AAI 60</b>.</div><p><b>Do not interpret AAI 60 as “60% dangerous,” “60% likely to fail,” or “60% safe.”</b> It means the scored authority/autonomy profile converts to 60 on AIM™'s standardized comparison scale.</p></div>
<div class="helpFormula"><h3>2. Weighted AAI</h3><div class="formulaLine">AAIᵥ = 100 × Σ(wᵢSᵢ) / (5Σwᵢ)</div><p><b>Sᵢ</b> is a dimension score and <b>wᵢ</b> is its assigned weight. Weighting allows an organization to give greater importance to dimensions that matter more in its validated context. Weights should be governed and justified rather than changed simply to obtain a preferred score.</p></div>
<div class="helpFormula"><h3>3. Authority Envelope</h3><div class="formulaLine">E = P ∩ D ∩ X ∩ F ∩ T ∩ L ∩ S ∩ Q</div><p>The <b>∩</b> symbol means intersection — effectively <b>AND</b>. The action must satisfy every applicable boundary.</p><div class="formulaTerms"><span><b>P</b> Purpose</span><span><b>D</b> Data</span><span><b>X</b> Action</span><span><b>F</b> Financial</span><span><b>T</b> Time</span><span><b>L</b> Delegation</span><span><b>S</b> Systems</span><span><b>Q</b> Consequence</span></div><p>If a $72,000 payment satisfies purpose, data, time, and system boundaries but the autonomous financial ceiling is $25,000, the action is outside the envelope.</p></div>
<div class="helpFormula"><h3>4. Permitted Action</h3><div class="formulaLine">Permitted Action = Constitution ∩ Authorization ∩ Authority Envelope</div><p>An action should proceed only when organizational rules, specific authorization, and the agent's operating envelope all permit it. One layer should not silently override the others.</p></div>
<div class="helpFormula"><h3>5. Sovereign Control / Last Command</h3><div class="formulaLine">Sovereign Control = External Revocation + Cessation Verification + Safe Reversion</div><p><b>External Revocation:</b> an authorized human can remove consequential authority through a mechanism the agent does not control. <b>Cessation Verification:</b> evidence confirms the authority actually stopped. <b>Safe Reversion:</b> operations can return to a known safe state.</p></div>
<div class="helpFormula"><h3>6. Decision Under Risk</h3><div class="formulaLine">a* = argmax[V(a) − λR(a)] subject to governance constraints</div><p>In plain English: choose the permitted action that creates the greatest expected value after accounting for risk — <b>but only among actions allowed by the organization's constitutional, authorization, and sovereignty constraints.</b> Optimization never creates authority.</p></div>
<div class="helpFormula"><h3>7. Authority Drift</h3><div class="formulaLine">ΔG = A_effective − A_approved</div><p>Compare what the agent can effectively do now with what was originally approved. A positive gap indicates authority has expanded through permissions, tools, integrations, delegation, configuration, or operating context and requires review.</p></div>`,
rx:`<h2>How to Read AIM™ Rx</h2><p>Rx is not a second questionnaire. It automatically interprets the completed Dx and answers: <b>Why does this agent have this exposure, and what should we change?</b></p>
<div class="helpBig"><b>Management Interpretation</b><p>This narrative is dynamic. It changes with the AAI, exposure band, highest authority concentrations, and the specific combination of capabilities. It should tell management what the profile means operationally rather than merely repeat the score.</p></div>
<div class="helpBig"><b>P1–P9 — Remediation Priorities</b><p><b>P means Priority, not Dimension.</b> P1 is the highest-priority remedy for this agent; P2 is next, and so forth. The priorities are dynamically ranked from the Dx profile. An agent may display fewer than nine priorities when fewer dimensions require material remediation.</p><p>Examples include reducing financial ceilings, restricting tool privileges, limiting delegation, throttling execution velocity, reducing operational scale, improving reversibility, or strengthening external human control.</p></div>
<div class="helpBig"><b>Modification Specification</b><p>Translates the diagnosis into engineering/operational language: current authority profile, target authority profile, and implementation requirements. It is intended to help product, engineering, security, compliance, and business owners act on the diagnosis.</p></div>
<div class="helpBig"><b>Verify the Fix</b><p>Rx does not lower the existing AAI because a recommendation was displayed or a control was planned. Implement the real authority change, then rerun Dx. The new score should describe the new actual authority profile.</p></div>`,
aghx:`<h2>A/G/H/X Boundary Guide</h2><p>A/G/H/X classifies how actions should be governed. Rx recommendations are dynamic and should ultimately be translated into enforceable controls.</p>
<div class="aghxHelp"><div><b>A — Autonomous</b><p>The agent may execute independently inside explicit approved boundaries. Good candidates are routine, reversible, observable actions with bounded consequence.</p><p><b>Example:</b> validate an invoice against an approved purchase order without releasing payment.</p></div>
<div><b>G — Gated</b><p>The agent may prepare or initiate the action, but execution requires a threshold, approval, dual control, technical gate, or other explicit condition.</p><p><b>Example:</b> a payment above the autonomous financial ceiling requires CFO authorization.</p></div>
<div><b>H — Human Reserved</b><p>The decision/action remains human because of consequence, irreversibility, exception authority, legal/institutional accountability, or sovereignty.</p><p><b>Example:</b> approving an exception that expands the agent's authority.</p></div>
<div><b>X — Prohibited</b><p>The agent may not perform the action. Prohibitions commonly include self-expansion, disabling monitoring or revocation, unauthorized banking changes, bypassing safety controls, or operating outside authorized purpose.</p></div></div>
<h3>How A/G/H/X relates to the Authority Envelope</h3><p>The envelope defines <b>where authority exists</b>. A/G/H/X defines <b>how specific actions are governed</b>. An action can be within the general mission yet still be Gated or Human Reserved because of amount, consequence, exception status, or irreversibility.</p>`,
terms:`<h2>AIM™ Glossary</h2><div class="helpGlossary"><p><b>AAI — AIM™ Autonomy Index:</b> standardized 0–100 comparison of the eleven scored authority/autonomy dimensions.</p><p><b>Authority:</b> the real-world consequences the agent is permitted and technically able to cause.</p><p><b>Autonomy:</b> the degree to which the agent operates independently inside delegated authority.</p><p><b>Authority Concentration:</b> multiple consequential powers accumulated in the same agent, identity, workflow, or control point.</p><p><b>Authority Envelope:</b> the intersection of Purpose, Data, Action, Financial, Time, Delegation, Systems, and Consequence boundaries.</p><p><b>Authority Drift:</b> change between approved authority and effective runtime authority.</p><p><b>Evidence:</b> records sufficient to reconstruct what the agent knew, what it used, what it decided, what it did, and what happened.</p><p><b>Tripwire:</b> a predefined condition that automatically pauses, reduces, or revokes authority.</p><p><b>Red Line:</b> an action or consequence the agent is never permitted to cross autonomously.</p><p><b>Non-Delegation:</b> the principle that an agent cannot delegate authority it does not possess or expand its own authority through sub-agents.</p><p><b>Last Command:</b> externally retained human capability to revoke authority, verify cessation, and safely revert.</p><p><b>Human-Control Deficit:</b> the degree to which meaningful human intervention is delayed, weak, dependent on the agent, or difficult to verify.</p></div>`
};
