function closeGlobalHelp(){document.getElementById("globalHelpModal").classList.remove("open")}
function helpTab(tab){document.getElementById("helpBody").innerHTML=aimHelp[tab]||aimHelp.quick}
document.addEventListener("keydown",e=>{if(e.key==="Escape")closeGlobalHelp()});
function renderRx(){
 const no=document.getElementById("rxNoDx"),content=document.getElementById("rxContent");
 if(!no||!content)return;
 const scores=Array.isArray(state.scores)&&state.scores.length===11?state.scores.map(Number):[];
 const aai=state.aai==null?null:Number(state.aai);
 if(scores.length!==11||aai==null||!Number.isFinite(aai)){
   no.classList.add("show");content.classList.add("hidden");return;
 }
 no.classList.remove("show");content.classList.remove("hidden");
 const meta=rxMeta(), band=rxBandLabel(aai);
 const ranked=rxControlMap.map((x,i)=>({...x,score:scores[i],i})).sort((a,b)=>b.score-a.score||a.i-b.i);
 const top=ranked.slice(0,3), elevated=ranked.filter(x=>x.score>=3);
 document.getElementById("rxAAI").textContent=aai.toFixed(1);
 document.getElementById("rxBand").textContent=band;
 document.getElementById("rxAgentTitle").textContent=meta.name+" — AIM™ Rx Evaluation";
 document.getElementById("rxExecutiveSummary").textContent=
   meta.name+" was assessed for the authorized purpose “"+meta.purpose+".” The Dx result is "+aai.toFixed(1)+
   "/100 ("+band+"). The prescription below focuses on changing the agent's actual authority architecture rather than administratively lowering the score.";

 const concentration=top.map(x=>x.name+" ("+x.score+"/5)").join(", ");
 document.getElementById("rxSituation").innerHTML=
   `<p><b>Overall evaluation.</b> ${meta.name} has an AAI of <b>${aai.toFixed(1)}</b>. Its most significant authority concentrations are ${concentration}. `+
   `The primary concern is the <b>combination</b> of these capabilities: ${rxCombinationAnalysis(top,meta)} `+
   `A single error, manipulated instruction, compromised credential, or misunderstood objective could therefore propagate into a consequential action.</p>`+
   `<p><b>Management interpretation.</b> ${rxManagementInterpretation(aai,top,scores,meta)}</p>`;

 document.getElementById("rxDrivers").innerHTML=top.map((x,i)=>
   `<div class="rx18Driver"><span class="rank">${i+1}</span><div><b>${x.name} — ${x.score}/5 · ${rxSeverity(x.score)}</b>`+
   `<p>${rxDriverExplanation(x)}</p><em>Why it matters: ${x.effect}</em></div></div>`).join("");

 const critical=ranked.filter(x=>x.score>=5);
 const high=ranked.filter(x=>x.score===4);
 const moderate=ranked.filter(x=>x.score===3);
 let remedySet;
 if(aai>=75) remedySet=[...critical,...high,...moderate].slice(0,7);
 else if(aai>=50) remedySet=[...critical,...high,...moderate].slice(0,5);
 else if(aai>=25) remedySet=[...critical,...high,...moderate].slice(0,3);
 else remedySet=ranked.filter(x=>x.score>=2).slice(0,2);
 if(!remedySet.length) remedySet=top.slice(0,1);
 document.getElementById("rxRemedyNarrative").innerHTML=
   `<p><b>Prescription objective:</b> reduce the agent's actual ability to create uncontrolled consequence while preserving useful automation. `+
   `The highest-value changes are to <b>remove authority the agent does not need</b>, <b>gate consequential authority that must remain</b>, and <b>make human revocation external and enforceable</b>. The priority list below is generated from this specific score profile; its <b>number, order, and recommended changes</b> vary with the agent.</p>`+
   `<p>For ${meta.name}, AIM™ Rx recommends addressing <b>${remedySet.slice(0,3).map(x=>x.name).join(", ")}</b> first. These changes should be implemented in the agent's permissions, workflow, credentials, transaction rules, orchestration layer, or surrounding control plane—not merely documented in policy.</p>`;

 document.getElementById("rxActionPlan").innerHTML=remedySet.map((x,i)=>{
   const d=rxDynamicAction(x,meta,aai);
   return `<div class="rx18Action"><div class="rx18Priority">P${i+1}</div><div>`+
   `<b>${x.name} — Current ${x.score}/5 · ${rxSeverity(x.score)}</b>`+
   `<p><strong>${d.lead}</strong> ${x.fix}${d.domain}</p>`+
   `<em>Target authority state after actual modification: ${d.target}/5 · ${x.effect}</em></div></div>`;
 }).join("");

 const highNames=top.map(x=>x.name);
 let current=`The agent currently carries its assessed authority across ${highNames.join(", ")}.`;
 let target=`Keep autonomous operation only inside the minimum authority needed for “${meta.purpose}.” Consequential actions should be gated or human-reserved; prohibited actions should be technically blocked.`;
 let controls=remedySet.slice(0,6).map(x=>`<li><b>${x.name}:</b> ${x.fix}</li>`).join("");
 document.getElementById("rxModification").innerHTML=
   `<div class="rx18Spec"><small>CURRENT AUTHORITY PROFILE</small><p>${current}</p></div>`+
   `<div class="rx18Arrow">→</div>`+
   `<div class="rx18Spec target"><small>TARGET AUTHORITY PROFILE</small><p>${target}</p></div>`+
   `<div class="rx18Build"><h3>Implementation Requirements</h3><ul>${controls}</ul></div>`;

 const boundaries=rxDynamicAGHX(meta,aai,scores,top);
 document.getElementById("rxAGHX").innerHTML=boundaries.map(x=>
   `<div class="rx18Boundary ${x.code}"><b>${x.code}</b><div><strong>${x.title}</strong>`+
   `<p>${x.intro}</p><ul>${x.items.map(item=>`<li>${item}</li>`).join("")}</ul></div></div>`
 ).join("");
}
