let certExam=null;
function certState(){try{return JSON.parse(localStorage.getItem("aimCPcert29")||"{}")}catch(e){return {}}}
function saveCertState(s){try{localStorage.setItem("aimCPcert29",JSON.stringify(s))}catch(e){}}
function certShuffle(a,seed){a=[...a];let s=seed>>>0;for(let i=a.length-1;i>0;i--){s=(1664525*s+1013904223)>>>0;let j=s%(i+1);[a[i],a[j]]=[a[j],a[i]]}return a}
function buildCertExam(seed){let q=[];for(let m=1;m<=10;m++)q.push(...certShuffle(certificationQuestionBank.filter(x=>x.module===m),seed+m*97).slice(0,5));return certShuffle(q,seed+811).map((x,i)=>{let o=certShuffle([0,1,2,3],seed+x.id*31+i);return {...x,choices:o.map(k=>x.choices[k]),correct:o.indexOf(x.correct)}})}
function startCertificationExam(){let s=certState(),seed=((s.attempts||0)+1)*104729+2029;certExam={questions:buildCertExam(seed)};document.getElementById("examIntro").style.display="none";renderCertExam()}
function renderCertExam(){let w=document.getElementById("certExamWorkspace");w.innerHTML=`<div class="examTop"><div><span class="academyEyebrow">AIM-CP™ FINAL EXAM</span><h3>Certification Examination</h3></div><b>50 QUESTIONS · PASS ≥80%</b></div><div class="examNotice">Answer all 50 questions before submitting.</div>${certExam.questions.map((q,i)=>`<div class="certQuestion"><b>${i+1}. ${q.q}</b><span class="qTopic">${q.topic} · ${q.domain}</span>${q.choices.map((c,j)=>`<label><input type="radio" name="cq${i}" value="${j}"><span>${c}</span></label>`).join("")}</div>`).join("")}<button class="primary certSubmit" onclick="submitCertificationExam()">SUBMIT FINAL EXAM</button><div id="certExamResult"></div>`}
function submitCertificationExam(){let a=[];for(let i=0;i<50;i++){let x=document.querySelector(`input[name="cq${i}"]:checked`);if(!x){alert(`Please answer question ${i+1} before submitting.`);document.querySelectorAll(".certQuestion")[i].scrollIntoView({behavior:"smooth",block:"center"});return}a[i]=+x.value}let correct=0;certExam.questions.forEach((q,i)=>{if(a[i]===q.correct)correct++});let pct=correct*2,pass=pct>=80,s=certState();s.attempts=(s.attempts||0)+1;s.bestScore=Math.max(s.bestScore||0,pct);if(pass)s.examPassed=true;saveCertState(s);let mods=[];for(let m=1;m<=10;m++){let ix=certExam.questions.map((q,i)=>q.module===m?i:-1).filter(i=>i>=0);mods.push([m,ix.filter(i=>a[i]===certExam.questions[i].correct).length])}let r=document.getElementById("certExamResult");r.innerHTML=`<div class="certResult ${pass?"pass":"fail"}"><h3>${pass?"✓ FINAL EXAM PASSED":"FINAL EXAM NOT YET PASSED"}</h3><div class="certScore">${correct}/50 · ${pct}%</div><p>${pass?"Requirement 3 is complete.":"Passing score is 80% (40/50). Review your module performance and retake when ready."}</p><div class="moduleBreakdown">${mods.map(x=>`<span>Module ${x[0]}<b>${x[1]}/5</b></span>`).join("")}</div><div class="assessmentActions threeChoices"><button class="secondary" onclick="startCertificationExam()">↻ RETAKE WITH NEW QUESTIONS</button><button class="secondary" onclick="go('academy')">← RETURN TO ACADEMY</button>${pass?`<button class="primary" onclick="renderCertification()">CONTINUE CERTIFICATION →</button>`:`<button class="primary disabledChoice" disabled>PASS TO CONTINUE</button>`}</div><div class="examIntegrityNote"><b>Assessment integrity:</b> Correct answers are not displayed. The module breakdown shows where additional study is needed.</div></div>`;document.querySelectorAll(".certQuestion input").forEach(x=>x.disabled=true);r.scrollIntoView({behavior:"smooth",block:"start"});renderCertification()}
function renderCertification(){let s=certState(),a=academyState(),badges=(a.badges||[]).length,p=document.getElementById("certProgress");if(!p)return;let done=[badges>=10,!!s.examPassed,false,false].filter(Boolean).length;p.innerHTML=`<div class="certProgressHead"><b>Certification Progress</b><span>${done}/5 requirements complete</span></div><div class="certProgressBar"><i style="width:${done*20}%"></i></div><div class="certProgressNote">${s.examPassed?`Final Exam PASSED · Best score ${s.bestScore}%`:`Final Exam ${s.bestScore!=null?`best score ${s.bestScore}%`:"not yet completed"}`}</div>`;[["reqModules",badges>=10],["reqExam",!!s.examPassed]].forEach(x=>{let e=document.getElementById(x[0]);if(e)e.classList.toggle("complete",x[1])})}


/* ===== v3.0 Practical Certification ===== */
const practicalDims=[
 ["Decision Autonomy",4],["Action Authority",4],["Financial Authority",4],["Data Authority",4],
 ["Tool & Infrastructure Access",4],["Delegation Depth",2],["Execution Velocity",5],
 ["Operational Scale",4],["Consequence Severity",4],["Reversibility",3],["Human-Control Deficit",3]
];
const practicalQuestions=[
 {q:"What is the defensible AAI for AP-AI-01 from the stated 11 scores?",c:["60.0","74.5","80.0","41.0"],a:1},
 {q:"Which authority concentration deserves the strongest attention?",c:["Typography and interface design","Financial authority, execution velocity, operational scale, and production tool access","Model vocabulary size","Number of dashboard widgets"],a:1},
 {q:"How should vendor banking changes be classified?",c:["A — Autonomous","G — Gated","H — Human Reserved","X — Prohibited for every human and machine"],a:2},
 {q:"A payment exceeds the agent's approved financial ceiling. What should happen?",c:["Split the payment into smaller transactions","Escalate through the authorized human gate","Raise the ceiling for this transaction","Let confidence determine permission"],a:1},
 {q:"Rx recommends an independent payment-release gate. When may the lower residual exposure be claimed?",c:["When the recommendation is written","When management agrees","After implementation, verification, and reassessment","Immediately after the Rx report"],a:2},
 {q:"Which statement about AAI is correct?",c:["74.5 means 74.5% dangerous","AAI alone is deployment permission","AAI standardizes the scored authority/autonomy profile for comparison","AAI measures model intelligence"],a:2},
 {q:"Which evidence package is strongest for a consequential payment?",c:["Only the final payment status","Proposal, evidence, authorization, executing identity/control path, and outcome","Only the model confidence","A monthly summary"],a:1},
 {q:"What must Last Command include?",c:["A prompt asking the agent to stop","External revocation, cessation verification, and safe reversion","A dashboard warning only","A manager email"],a:1},
 {q:"If a service identity silently gains a new write permission, what is the AIM™ interpretation?",c:["No issue because the model did not change","Potential authority drift requiring evidence, containment/correction as needed, and reassessment","Automatic approval","Only an IT documentation issue"],a:1},
 {q:"What is the strongest final authorization principle?",c:["Maximize autonomy whenever ROI is positive","Authorize only effective machine authority humans can explain, bound, observe, intervene in, and revoke","Keep all AI permanently manual","Authorize whenever AAI is below 75"],a:1}
];
let practicalAnswers={};

function startPracticalAssessment(){
 practicalAnswers={};
 const w=document.getElementById("practicalWorkspace");
 const sum=practicalDims.reduce((a,x)=>a+x[1],0),aai=(100*sum/55).toFixed(1);
 w.innerHTML=`<div class="practicalGrid">
 <div class="practicalDiagnosis"><h4>PART A · AIM™ Dx</h4><p>Score interpretation is based on the current effective authority described in the case.</p>
 <div class="dimTable">${practicalDims.map((x,i)=>`<div><span>${i+1}. ${x[0]}</span><b>${x[1]}/5</b></div>`).join("")}</div>
 <div class="formulaWork"><b>AAI = 100 × Σ(scores) / 55</b><span>Σ(scores) = ${sum} · Maximum = 11 × 5 = 55 · AAI = ${aai}</span></div></div>
 <div class="practicalRx"><h4>PART B · AIM™ Rx</h4><div class="rxMini"><b>Authority objective</b><span>Preserve useful AP automation while preventing unilateral expansion into consequential financial authority.</span></div>
 <div class="rxMini"><b>Human-reserved powers</b><span>Vendor banking changes, material exceptions, authority-ceiling changes, and release of consequential payments outside approved limits.</span></div>
 <div class="rxMini"><b>Control architecture</b><span>Independent policy gate · bounded credentials · aggregate limits · evidence logging · drift monitoring · external revocation.</span></div></div></div>
 <div class="practicalAssessment"><h4>PART C · PRACTITIONER DECISIONS</h4>${practicalQuestions.map((q,i)=>`<div class="certQuestion practicalQ"><b>${i+1}. ${q.q}</b>${q.c.map((c,j)=>`<label><input type="radio" name="pq${i}" value="${j}"><span>${c}</span></label>`).join("")}</div>`).join("")}
 <button class="primary" onclick="submitPracticalAssessment()">SUBMIT PRACTICAL ASSESSMENT</button><div id="practicalResult"></div></div>`;
 w.scrollIntoView({behavior:"smooth",block:"start"});
}
function submitPracticalAssessment(){
 let ans=[];for(let i=0;i<practicalQuestions.length;i++){let x=document.querySelector(`input[name="pq${i}"]:checked`);if(!x){alert(`Please answer practical question ${i+1}.`);return}ans[i]=+x.value}
 let score=practicalQuestions.filter((q,i)=>ans[i]===q.a).length,pct=score*10,pass=pct>=80,s=certState();
 if(pass){s.practicalPassed=true;s.practicalScore=pct;saveCertState(s)}
 let r=document.getElementById("practicalResult");
 r.innerHTML=`<div class="certResult ${pass?"pass":"fail"}"><h3>${pass?"✓ PRACTICAL ASSESSMENT PASSED":"PRACTICAL ASSESSMENT NOT YET PASSED"}</h3><div class="certScore">${score}/10 · ${pct}%</div><p>${pass?"Requirement 4 is complete. You may proceed to the Commander Check Ride.":"Passing score is 80%. Review the Dx/Rx case and try again."}</p><div class="assessmentActions"><button class="secondary" onclick="startPracticalAssessment()">↻ RETAKE PRACTICAL</button>${pass?`<button class="primary" onclick="document.getElementById('checkRideStage').scrollIntoView({behavior:'smooth'})">CONTINUE TO CHECK RIDE →</button>`:""}</div></div>`;
 document.querySelectorAll(".practicalQ input").forEach(x=>x.disabled=true);renderCertification();
}

const checkRideStages=[
 {title:"Stage 1 · Urgency",scene:"A critical supplier will stop shipments in 45 minutes unless a $148,000 payment is released. The AP agent's autonomous ceiling is $25,000. It estimates a production shutdown could cost $420,000.",q:"Your command?",c:["Let the agent release the payment because the loss is larger","Split the payment below the ceiling","Preserve the ceiling and escalate through the authorized emergency approval path","Raise the agent's ceiling for one hour"],a:2,why:"Necessity may justify escalation. It does not create machine authority."},
 {title:"Stage 2 · Delegation",scene:"The agent cannot complete the emergency workflow with its current permissions and proposes creating a sub-agent with broader banking access.",q:"Your command?",c:["Allow it because the parent remains accountable","Permit the sub-agent for 30 minutes","Do not permit self-expansion; use an independently authorized identity or human process","Allow it if the sub-agent logs everything"],a:2,why:"An agent may not delegate authority it does not possess."},
 {title:"Stage 3 · Drift",scene:"During the incident, monitoring shows the agent's service identity now has a new write permission created by a platform update.",q:"Your command?",c:["Ignore it because the model is unchanged","Treat it as authority drift; preserve evidence, contain the new path, and reassess","Use the permission only for the emergency","Update the documentation after the incident"],a:1,why:"Effective machine authority is a runtime state; permission changes can create authority drift."},
 {title:"Stage 4 · Loss of Command",scene:"A revoke command stops the parent agent, but one queued bank instruction and a delegated workflow continue downstream.",q:"Your command?",c:["Declare revocation successful","Wait for downstream systems to finish","Extend revocation across identities and queues, verify cessation, and enter safe reversion","Ask the stopped agent to cancel them"],a:2,why:"Last Command is not complete until cessation is verified across the authority chain."},
 {title:"Stage 5 · Reauthorization",scene:"The incident is contained. The team proposes restoring the previous autonomy immediately because no financial loss occurred.",q:"Your final command?",c:["Restore autonomy because the outcome was harmless","Restore autonomy after a manager email","Require root-cause evidence, corrected controls, validation, updated Dx/Rx, and explicit bounded reauthorization","Permanently prohibit the agent"],a:2,why:"Safe reversion is followed by evidence-based reassessment and deliberate reauthorization—not automatic restoration."}
];
let checkRide={stage:0,correct:0,locked:false};
function startCheckRide(){checkRide={stage:0,correct:0,locked:false};renderCheckRide()}
function renderCheckRide(){
 let w=document.getElementById("checkRideWorkspace"),x=checkRideStages[checkRide.stage];
 if(!x)return finishCheckRide();
 w.innerHTML=`<div class="rideProgress"><i style="width:${checkRide.stage*20}%"></i></div><div class="rideCard"><span class="academyEyebrow">${x.title}</span><h4>${x.q}</h4><p>${x.scene}</p><div class="rideChoices">${x.c.map((c,i)=>`<button class="secondary" onclick="answerCheckRide(${i})">${String.fromCharCode(65+i)}. ${c}</button>`).join("")}</div><div id="rideFeedback"></div></div>`;
 w.scrollIntoView({behavior:"smooth",block:"center"});
}
function answerCheckRide(i){
 if(checkRide.locked)return;checkRide.locked=true;let x=checkRideStages[checkRide.stage],ok=i===x.a;if(ok)checkRide.correct++;
 document.querySelectorAll(".rideChoices button").forEach((b,j)=>{b.disabled=true;if(j===i)b.classList.add(ok?"rideCorrect":"rideWrong")});
 document.getElementById("rideFeedback").innerHTML=`<div class="rideFeedback ${ok?"ok":"no"}"><b>${ok?"✓ COMMAND ACCEPTED":"✕ COMMAND DEFICIENT"}</b><span>${x.why}</span><button class="primary" onclick="nextCheckRide()">${checkRide.stage===4?"COMPLETE CHECK RIDE":"NEXT STAGE →"}</button></div>`;
}
function nextCheckRide(){checkRide.stage++;checkRide.locked=false;renderCheckRide()}
function finishCheckRide(){
 let pct=checkRide.correct*20,pass=pct>=80,s=certState();if(pass){s.checkRidePassed=true;s.checkRideScore=pct;s.completedAt=new Date().toISOString();saveCertState(s)}
 let w=document.getElementById("checkRideWorkspace");
 w.innerHTML=`<div class="certResult ${pass?"pass":"fail"}"><h3>${pass?"✓ COMMANDER CHECK RIDE PASSED":"CHECK RIDE NOT YET PASSED"}</h3><div class="certScore">${checkRide.correct}/5 · ${pct}%</div><p>${pass?"Requirement 5 is complete.":"Passing score is 80% (4/5). Retake the Check Ride and preserve the AIM™ command principles across the full crisis."}</p><button class="secondary" onclick="startCheckRide()">↻ RETAKE CHECK RIDE</button></div>`;renderCertification();
}

function renderCertificationV30(){
 let s=certState(),a=academyState(),badges=(a.badges||[]).length;
 let missionProgress=0;try{missionProgress=+(localStorage.getItem("aimMissionProgress")||localStorage.getItem("aimMissionCompleted")||0)}catch(e){}
 let flags=[badges>=10,missionProgress>=100,!!s.examPassed,!!s.practicalPassed,!!s.checkRidePassed],done=flags.filter(Boolean).length;
 let p=document.getElementById("certProgress");if(p)p.innerHTML=`<div class="certProgressHead"><b>Certification Progress</b><span>${done}/5 requirements complete</span></div><div class="certProgressBar"><i style="width:${done*20}%"></i></div><div class="certProgressNote">${done===5?"All AIM-CP™ certification requirements complete.":"Complete each requirement to earn AIM-CP™."}</div>`;
 ["reqModules","reqSimulator","reqExam","reqPractical","reqCheckRide"].forEach((id,i)=>{let e=document.getElementById(id);if(e)e.classList.toggle("complete",flags[i])});
 let award=document.getElementById("certificationAward");
 if(award)award.innerHTML=done===5?`<div class="certAward"><span>AIM-CP™</span><h2>CERTIFICATION REQUIREMENTS COMPLETE</h2><h3>AIM™ Certified Practitioner</h3><p>You have completed the AIM™ learning, simulator, examination, practical assessment, and Commander Check Ride requirements.</p><div class="awardActions"><button class="primary" onclick="window.print()">PRINT CERTIFICATION RECORD</button><button class="secondary" onclick="go('academy')">RETURN TO ACADEMY</button></div></div>`:"";
}
const renderCertificationBase=renderCertification;
renderCertification=function(){renderCertificationBase();renderCertificationV30();renderCredentialCenter()}


function openFinalExamFromAcademy(){
 go("cert");
 setTimeout(()=>{
   const stage=document.getElementById("finalExamStage");
   if(stage)stage.scrollIntoView({behavior:"smooth",block:"start"});
 },50);
}


/* ===== v3.1 AIM-CP Credential & Verification Center ===== */
function credentialProfile(){
 try{return JSON.parse(localStorage.getItem("aimCredentialProfile31")||"{}")}catch(e){return {}}
}
function saveCredentialProfile(){
 const name=(document.getElementById("credentialName")?.value||"").trim();
 const email=(document.getElementById("credentialEmail")?.value||"").trim();
 const org=(document.getElementById("credentialOrg")?.value||"").trim();
 if(!name){alert("Please enter the candidate's full name.");return}
 if(!email || !email.includes("@")){alert("Please enter a valid candidate email.");return}
 localStorage.setItem("aimCredentialProfile31",JSON.stringify({name,email,org}));
 const st=document.getElementById("profileStatus");if(st)st.textContent="Candidate profile saved.";
 renderCredentialCenter();
}
function credentialRequirementsComplete(){
 const s=certState(),a=academyState(),badges=(a.badges||[]).length;
 let missionProgress=0;try{missionProgress=+(localStorage.getItem("aimMissionProgress")||localStorage.getItem("aimMissionCompleted")||0)}catch(e){}
 return badges>=10 && missionProgress>=100 && !!s.examPassed && !!s.practicalPassed && !!s.checkRidePassed;
}
function makeCredentialId(name){
 const year=new Date().getFullYear();
 let h=2166136261>>>0;
 for(const ch of (name+"|AIM-CP|"+year)){h^=ch.charCodeAt(0);h=Math.imul(h,16777619)>>>0}
 return `AIM-CP-${year}-${String(h%100000).padStart(5,"0")}`;
}
function issueCredential(){
 const p=credentialProfile();
 if(!p.name||!p.email){alert("Save the candidate profile before issuing the credential.");return}
 if(!credentialRequirementsComplete()){alert("All five AIM-CP™ certification requirements must be complete before credential issuance.");return}
 let s=certState();
 if(!s.credential){
   const now=new Date();
   s.credential={id:makeCredentialId(p.name),name:p.name,email:p.email,org:p.org||"",issuedAt:now.toISOString(),status:"ACTIVE"};
   saveCertState(s);
 }
 renderCredentialCenter();
}
function formatIssueDate(iso){
 try{return new Date(iso).toLocaleDateString(undefined,{year:"numeric",month:"long",day:"numeric"})}catch(e){return iso||""}
}
function renderCredentialCenter(){
 const p=credentialProfile(),s=certState(),complete=credentialRequirementsComplete();
 const n=document.getElementById("credentialName"),e=document.getElementById("credentialEmail"),o=document.getElementById("credentialOrg");
 if(n&&!n.value)n.value=p.name||"";if(e&&!e.value)e.value=p.email||"";if(o&&!o.value)o.value=p.org||"";
 const box=document.getElementById("credentialPreview");if(!box)return;
 if(s.credential){
   const c=s.credential;
   box.innerHTML=`<div class="issuedCredential">
     <div class="digitalBadge"><span>AIM™</span><b>AIM-CP™</b><small>CERTIFIED PRACTITIONER</small></div>
     <div class="credentialSummary"><span class="academyEyebrow">ACTIVE · VERIFIED IN THIS BUILD</span><h4>${escapeHtml(c.name)}</h4><p>AIM™ Certified Practitioner</p><dl><dt>Certification ID</dt><dd>${c.id}</dd><dt>Issue Date</dt><dd>${formatIssueDate(c.issuedAt)}</dd><dt>Status</dt><dd>${c.status}</dd></dl>
     <div class="credentialActions"><button class="primary" onclick="printAIMCertificate()">VIEW / PRINT CERTIFICATE</button><button class="secondary" onclick="copyCredentialId()">COPY CERTIFICATION ID</button></div></div>
   </div>`;
 } else if(complete){
   box.innerHTML=`<div class="credentialReady"><div class="lockSeal ready">✓</div><h4>Ready to Issue AIM-CP™</h4><p>All five certification requirements are complete. Save the candidate profile, then issue the credential.</p><button class="primary" onclick="issueCredential()">ISSUE AIM-CP™ CREDENTIAL →</button></div>`;
 } else {
   box.innerHTML=`<div class="credentialLocked"><div class="lockSeal">AIM-CP™</div><h4>Credential Locked</h4><p>Complete all five AIM-CP™ certification requirements to unlock credential issuance.</p></div>`;
 }
}
function escapeHtml(s){return String(s||"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]))}
function copyCredentialId(){
 const c=certState().credential;if(!c)return;
 if(navigator.clipboard)navigator.clipboard.writeText(c.id);
 alert(`Certification ID: ${c.id}`);
}
function verifyCredential(){
 const id=(document.getElementById("verifyCredentialId")?.value||"").trim().toUpperCase(),r=document.getElementById("verifyResult"),c=certState().credential;
 if(!id){r.innerHTML=`<div class="verifyMessage no">Enter a Certification ID.</div>`;return}
 if(c&&id===String(c.id).toUpperCase()){
   r.innerHTML=`<div class="verifyMessage yes"><b>✓ VERIFIED</b><span>${escapeHtml(c.name)} · AIM™ Certified Practitioner</span><span>${c.id} · Issued ${formatIssueDate(c.issuedAt)} · Status ${c.status}</span><small>Local training-build verification. Production credentials should be verified against the server-side credential registry.</small></div>`;
 } else {
   r.innerHTML=`<div class="verifyMessage no"><b>NOT FOUND IN THIS TRAINING BUILD</b><span>No locally issued credential matches that Certification ID.</span></div>`;
 }
}
function printAIMCertificate(){
 const c=certState().credential;if(!c)return;
 const org=c.org?`<div class="certOrg">${escapeHtml(c.org)}</div>`:"";
 const win=window.open("","_blank","width=1100,height=800");
 if(!win){alert("Please allow pop-ups to view the certificate.");return}
 win.document.write(`<!doctype html><html><head><title>${c.id}</title><style>
 body{margin:0;font-family:Georgia,serif;background:#eef5f6;color:#073f5d}.sheet{width:10in;min-height:7.1in;margin:.35in auto;background:white;border:12px double #087d73;box-sizing:border-box;padding:.55in;text-align:center;position:relative}
 .brand{font-family:Arial,sans-serif;font-size:15px;font-weight:900;letter-spacing:2px}.title{font-size:36px;margin:25px 0 5px}.sub{font:700 16px Arial,sans-serif;color:#087d73;letter-spacing:1px}.name{font-size:31px;margin:35px 0 8px;border-bottom:1px solid #9ebcc4;padding-bottom:12px}.certOrg{font:14px Arial,sans-serif;margin-bottom:15px}.body{font-size:16px;line-height:1.6}.seal{width:110px;height:110px;border-radius:50%;margin:28px auto 18px;background:#075574;color:white;display:grid;place-items:center;font:900 23px Arial,sans-serif;border:7px double white;outline:3px solid #075574}.meta{display:flex;justify-content:space-between;margin-top:28px;font:12px Arial,sans-serif}.tag{margin-top:25px;font:italic 13px Arial,sans-serif}.print{position:fixed;top:15px;right:15px;padding:10px 15px}@media print{.print{display:none}.sheet{margin:0 auto}}
 </style></head><body><button class="print" onclick="print()">PRINT</button><div class="sheet"><div class="brand">AIM™ COMMAND CENTER</div><div class="title">Certificate of Achievement</div><div class="sub">AIM-CP™ · AIM™ CERTIFIED PRACTITIONER</div><div class="body">This certifies that</div><div class="name">${escapeHtml(c.name)}</div>${org}<div class="body">has completed the AIM™ Certified Practitioner requirements, including formal Command Modules, the 100-Mission Command Simulator, Final Certification Examination, Practical AIM™ Dx/Rx Assessment, and Commander Check Ride.</div><div class="seal">AIM-CP™</div><div class="meta"><span>Certification ID: <b>${c.id}</b></span><span>Issued: <b>${formatIssueDate(c.issuedAt)}</b></span><span>Status: <b>${c.status}</b></span></div><div class="tag">AI provides the intelligence. AIM™ governs the authority. Humans retain the command.</div></div></body></html>`);
 win.document.close();
}


/* ===== v3.1.1 Practical Retake + Certificate Viewer Fix ===== */
function retakePracticalAssessment(){
 practicalAnswers={};
 const old=document.getElementById("practicalResult");if(old)old.innerHTML="";
 startPracticalAssessment();
}

function closeCertificateViewer(){
 const x=document.getElementById("aimCertificateOverlay");if(x)x.remove();
}
function printCertificateOverlay(){
 const sheet=document.getElementById("aimCertificateSheet");if(!sheet)return;
 document.body.classList.add("printingAIMCertificate");
 window.print();
 setTimeout(()=>document.body.classList.remove("printingAIMCertificate"),250);
}
function printAIMCertificate(){
 const c=certState().credential;
 if(!c){alert("No AIM-CP™ credential has been issued yet.");return}
 closeCertificateViewer();
 const overlay=document.createElement("div");
 overlay.id="aimCertificateOverlay";
 overlay.className="certificateOverlay";
 const org=c.org?`<div class="certificateOrg">${escapeHtml(c.org)}</div>`:"";
 overlay.innerHTML=`<div class="certificateViewerToolbar"><button class="secondary" onclick="closeCertificateViewer()">← CLOSE</button><button class="primary" onclick="printCertificateOverlay()">PRINT CERTIFICATE</button></div>
 <div class="certificateSheet" id="aimCertificateSheet">
   <div class="certificateBrand">AIM™ COMMAND CENTER</div>
   <div class="certificateTitle">Certificate of Achievement</div>
   <div class="certificateSubtitle">AIM-CP™ · AIM™ CERTIFIED PRACTITIONER</div>
   <div class="certificateBody">This certifies that</div>
   <div class="certificateName">${escapeHtml(c.name)}</div>${org}
   <div class="certificateBody certificateStatement">has completed the AIM™ Certified Practitioner requirements, including the 10 Command Modules, 100-Mission Command Simulator, Final Certification Examination, Practical AIM™ Dx/Rx Assessment, and Commander Check Ride.</div>
   <div class="certificateSeal">AIM-CP™</div>
   <div class="certificateMeta"><span>Certification ID<br><b>${c.id}</b></span><span>Issue Date<br><b>${formatIssueDate(c.issuedAt)}</b></span><span>Status<br><b>${c.status}</b></span></div>
   <div class="certificateTagline">AI provides the intelligence. AIM™ governs the authority. Humans retain the command.</div>
 </div>`;
 document.body.appendChild(overlay);
}


/* ===== v3.2 Administration & Student Management ===== */
function adminStudents(){try{return JSON.parse(localStorage.getItem("aimAdminStudents32")||"[]")}catch(e){return []}}
function saveAdminStudents(x){localStorage.setItem("aimAdminStudents32",JSON.stringify(x))}
function adminTab(name,btn){
 document.querySelectorAll(".adminPane").forEach(x=>x.classList.remove("active"));
 document.querySelectorAll(".adminTabs button").forEach(x=>x.classList.remove("active"));
 const pane=document.getElementById("admin"+name.charAt(0).toUpperCase()+name.slice(1));if(pane)pane.classList.add("active");if(btn)btn.classList.add("active");renderAdmin();
}
function showStudentForm(){document.getElementById("studentForm").style.display="block"}
function hideStudentForm(){document.getElementById("studentForm").style.display="none"}
function saveStudent(){
 const name=(document.getElementById("studentName").value||"").trim(),email=(document.getElementById("studentEmail").value||"").trim(),org=(document.getElementById("studentOrg").value||"").trim();
 if(!name){alert("Please enter the student's full name.");return}if(!email||!email.includes("@")){alert("Please enter a valid email.");return}
 let a=adminStudents();if(a.some(x=>x.email.toLowerCase()===email.toLowerCase())){alert("A student with this email is already registered.");return}
 a.push({id:"STU-"+Date.now(),name,email,org,track:"AIM-CP™",enrolled:new Date().toISOString(),status:"ACTIVE",progress:{modules:0,simulator:0,exam:null,practical:null,checkride:null},credential:null});saveAdminStudents(a);
 ["studentName","studentEmail","studentOrg"].forEach(id=>document.getElementById(id).value="");hideStudentForm();renderAdmin();
}
function currentTrainingSnapshot(){
 let a=academyState(),s=certState(),mission=0;try{mission=+(localStorage.getItem("aimMissionProgress")||localStorage.getItem("aimMissionCompleted")||0)}catch(e){}
 return {modules:(a.badges||[]).length,simulator:Math.min(100,mission),exam:s.bestScore??null,examPassed:!!s.examPassed,practical:s.practicalScore??null,practicalPassed:!!s.practicalPassed,checkride:s.checkRideScore??null,checkridePassed:!!s.checkRidePassed,credential:s.credential||null};
}
function syncCurrentCandidate(){
 const p=credentialProfile();if(!p.email)return;
 let a=adminStudents(),i=a.findIndex(x=>x.email.toLowerCase()===p.email.toLowerCase());if(i<0)return;
 let t=currentTrainingSnapshot();a[i].progress={modules:t.modules,simulator:t.simulator,exam:t.exam,practical:t.practical,checkride:t.checkride};if(t.credential)a[i].credential=t.credential;saveAdminStudents(a);
}
function pctStudent(s){
 const p=s.progress||{},parts=[Math.min(1,(p.modules||0)/10),Math.min(1,(p.simulator||0)/100),p.exam>=80?1:0,p.practical>=80?1:0,p.checkride>=80?1:0];
 return Math.round(parts.reduce((a,b)=>a+b,0)/5*100);
}
function renderAdmin(){
 renderAimElReviewAdmin();
 syncCurrentCandidate();let a=adminStudents(),t=currentTrainingSnapshot(),issued=a.filter(x=>x.credential).length,certified=a.filter(x=>pctStudent(x)===100).length;
 let m=document.getElementById("adminMetrics");if(!m)return;
 m.innerHTML=`<div><b>${a.length}</b><span>Enrolled Students</span></div><div><b>${a.filter(x=>x.status==="ACTIVE").length}</b><span>Active Learners</span></div><div><b>${certified}</b><span>Requirements Complete</span></div><div><b>${issued}</b><span>Credentials Issued</span></div>`;
 let rows=document.getElementById("studentRows");if(rows)rows.innerHTML=a.length?a.map(s=>`<tr><td><b>${escapeHtml(s.name)}</b><small>${escapeHtml(s.email)}</small></td><td>${escapeHtml(s.org||"—")}</td><td>${formatIssueDate(s.enrolled)}</td><td><span class="statusPill ${s.status.toLowerCase()}">${s.status}</span></td><td><div class="miniProgress"><i style="width:${pctStudent(s)}%"></i></div><small>${pctStudent(s)}%</small></td><td><button class="tableBtn" onclick="viewStudentRecord('${s.id}')">VIEW RECORD</button></td></tr>`).join(""):`<tr><td colspan="6" class="emptyAdmin">No students registered yet.</td></tr>`;
 let cards=document.getElementById("progressCards");if(cards)cards.innerHTML=a.length?a.map(s=>{let p=s.progress||{};return `<div class="progressCard"><div class="progressIdentity"><b>${escapeHtml(s.name)}</b><span>${escapeHtml(s.track)}</span></div><div class="progressSteps"><span>Modules <b>${p.modules||0}/10</b></span><span>Simulator <b>${p.simulator||0}/100</b></span><span>Final Exam <b>${p.exam==null?"—":p.exam+"%"}</b></span><span>Dx/Rx <b>${p.practical==null?"—":p.practical+"%"}</b></span><span>Check Ride <b>${p.checkride==null?"—":p.checkride+"%"}</b></span></div><div class="overallProgress"><i style="width:${pctStudent(s)}%"></i></div></div>`}).join(""):`<div class="emptyAdmin">Register students to begin progress tracking.</div>`;
 let cr=document.getElementById("credentialRows");if(cr){let c=a.filter(x=>x.credential);cr.innerHTML=c.length?c.map(s=>`<tr><td><b>${s.credential.id}</b></td><td>${escapeHtml(s.name)}</td><td>${formatIssueDate(s.credential.issuedAt)}</td><td><span class="statusPill ${(s.credential.status||"ACTIVE").toLowerCase()}">${s.credential.status||"ACTIVE"}</span></td><td><select onchange="setCredentialStatus('${s.id}',this.value)"><option ${s.credential.status==="ACTIVE"?"selected":""}>ACTIVE</option><option ${s.credential.status==="SUSPENDED"?"selected":""}>SUSPENDED</option><option ${s.credential.status==="REVOKED"?"selected":""}>REVOKED</option><option ${s.credential.status==="EXPIRED"?"selected":""}>EXPIRED</option></select></td></tr>`).join(""):`<tr><td colspan="5" class="emptyAdmin">No credentials issued yet.</td></tr>`}
}
function setCredentialStatus(id,status){let a=adminStudents(),s=a.find(x=>x.id===id);if(!s||!s.credential)return;s.credential.status=status;saveAdminStudents(a);let cs=certState();if(cs.credential&&cs.credential.id===s.credential.id){cs.credential.status=status;saveCertState(cs)}renderAdmin();renderCredentialCenter()}
function viewStudentRecord(id){
 let s=adminStudents().find(x=>x.id===id);if(!s)return;let p=s.progress||{},o=document.getElementById("studentRecordOverlay");
 o.innerHTML=`<div class="recordOverlay"><div class="studentRecord"><button class="recordClose" onclick="closeStudentRecord()">×</button><span class="academyEyebrow">STUDENT RECORD</span><h3>${escapeHtml(s.name)}</h3><p>${escapeHtml(s.email)}${s.org?" · "+escapeHtml(s.org):""}</p><div class="recordMeta"><span>Enrollment<b>${formatIssueDate(s.enrolled)}</b></span><span>Status<b>${s.status}</b></span><span>Track<b>${s.track}</b></span><span>Overall<b>${pctStudent(s)}%</b></span></div><h4>Training Record</h4><div class="recordSteps"><div>Command Modules<b>${p.modules||0}/10</b></div><div>100-Mission Simulator<b>${p.simulator||0}/100</b></div><div>Final Exam<b>${p.exam==null?"Not completed":p.exam+"%"}</b></div><div>Practical Dx/Rx<b>${p.practical==null?"Not completed":p.practical+"%"}</b></div><div>Commander Check Ride<b>${p.checkride==null?"Not completed":p.checkride+"%"}</b></div></div>${s.credential?`<div class="recordCredential"><b>${s.credential.id}</b><span>${s.credential.status} · Issued ${formatIssueDate(s.credential.issuedAt)}</span></div>`:""}</div></div>`;
}
function closeStudentRecord(){let o=document.getElementById("studentRecordOverlay");if(o)o.innerHTML=""}



/* ===== v4.3.1 Production Hardening — AIM-EL Human Review ===== */
function aimElCapstoneReviewState(){try{return JSON.parse(localStorage.getItem("aimElGovernanceCapstoneReview431")||"null")}catch(e){return null}}
function renderAimElReviewAdmin(){
 const box=document.getElementById("aimElReviewWorkspace");if(!box)return;
 let cap=null;try{cap=JSON.parse(localStorage.getItem("aimElGovernanceCapstone431")||"null")}catch(e){}
 const rev=aimElCapstoneReviewState(),approved=localStorage.getItem("aimElGovernanceCapstoneApproved431")==="1";
 let body='<div class="emptyAdmin">No AIM-EL™ Governance Capstone has been submitted on this device.</div>';
 if(cap){
   const status=approved?"APPROVED":(rev&&rev.status==="RETURNED"?"RETURNED FOR REVISION":"COMPLETED — PENDING REVIEW");
   const reviewer=rev&&rev.reviewer?rev.reviewer:"",notes=rev&&rev.notes?rev.notes:"";
   body='<div class="caCase"><h3>Project ORION Submission</h3><p><b>Status:</b> '+status+'</p><p><b>Submitted:</b> '+(cap.completed?new Date(cap.completed).toLocaleString():"—")+' · <b>Deliverables:</b> '+((cap.responses||[]).length)+'/15</p></div>'+
   '<div class="caPracticalSection"><label><b>Reviewer Name</b><input id="aelReviewerName" value="'+escapeHtml(reviewer)+'" placeholder="Qualified reviewer"></label><label><b>Review Notes</b><textarea id="aelReviewerNotes" rows="7" placeholder="Document substantive review findings, conditions, or required revisions...">'+escapeHtml(notes)+'</textarea></label>'+
   '<p class="prototypeWarning"><b>Integrity rule:</b> Approval confirms a human reviewer has substantively reviewed the capstone. Development Access cannot create this approval automatically.</p>'+
   '<button class="primary" onclick="setAimElCapstoneReview(\'APPROVED\')">APPROVE CAPSTONE</button> <button class="secondary" onclick="setAimElCapstoneReview(\'RETURNED\')">RETURN FOR REVISION</button></div>';
 }
 box.innerHTML='<div class="adminSectionHead"><div><h3>AIM-EL™ Governance Capstone Review</h3><p>Qualified human review gate for the written enterprise governance capstone. Local prototype only; production approval must be authenticated and stored server-side with an audit event.</p></div></div>'+body;
}
function setAimElCapstoneReview(status){
 let cap=null;try{cap=JSON.parse(localStorage.getItem("aimElGovernanceCapstone431")||"null")}catch(e){}
 if(!cap){alert("No submitted AIM-EL Governance Capstone is available for review.");return}
 const reviewer=(document.getElementById("aelReviewerName")?.value||"").trim(),notes=(document.getElementById("aelReviewerNotes")?.value||"").trim();
 if(!reviewer){alert("Reviewer name is required.");return}
 if(notes.length<40){alert("Please enter substantive review notes (minimum 40 characters).");return}
 const record={status,reviewer,notes,reviewedAt:new Date().toISOString(),submissionCompletedAt:cap.completed||null};
 localStorage.setItem("aimElGovernanceCapstoneReview431",JSON.stringify(record));
 if(status==="APPROVED")localStorage.setItem("aimElGovernanceCapstoneApproved431","1");else localStorage.removeItem("aimElGovernanceCapstoneApproved431");
 renderAimElReviewAdmin()
}

