 let displayName=(document.getElementById("protoDisplayName")?.value||"").trim(),email=(document.getElementById("protoEmail")?.value||"").trim(),role=document.getElementById("protoRole")?.value||"ADMIN";
 if(email&&!email.includes("@")){alert("Please enter a valid email.");return}
