/* ===== v4.3.1 Dedicated Certificate Page ===== */
function openCertificatePage(){go("certificate");setTimeout(renderCertificateOnlyPage,20)}
function renderCertificateOnlyPage(){
 const box=document.getElementById("certificateOnlyContent");if(!box)return;
 const s=certState(),c=s.credential,p=credentialProfile(),complete=credentialRequirementsComplete();
 if(c){
   box.innerHTML=`<div class="certificateOnlyCard"><div class="certificateSeal">AIM-CP™</div><span class="credentialStatus ${String(c.status||"ACTIVE").toLowerCase()}">${escapeHtml(c.status||"ACTIVE")}</span><h3>AIM™ Certified Practitioner</h3><div class="certificateCandidate">${escapeHtml(c.name||p.name||"")}</div>${c.org?`<div class="certificateOrg">${escapeHtml(c.org)}</div>`:""}<div class="certificateMeta"><div><b>Certification ID</b><span>${escapeHtml(c.id)}</span></div><div><b>Issued</b><span>${formatIssueDate(c.issuedAt)}</span></div></div><div class="certificatePageButtons"><button class="primary" onclick="printAIMCertificate()">VIEW / PRINT CERTIFICATE</button><button class="secondary" onclick="copyCredentialId()">COPY CERTIFICATION ID</button></div><div class="certificateVerifyNote">Credential verification reflects the current credential status recorded by AIM™ Command Center.</div></div>`;
 } else if(complete){
   box.innerHTML=`<div class="certificateOnlyCard certificateReadyOnly"><div class="certificateSeal">✓</div><h3>Certification Requirements Complete</h3><p>Your requirements are complete. Issue the AIM-CP™ credential from the Certification Center to generate the certificate.</p><button class="primary" onclick="go('cert')">ISSUE CREDENTIAL →</button></div>`;
 } else {
   box.innerHTML=`<div class="certificateOnlyCard certificateLockedOnly"><div class="certificateSeal">AIM-CP™</div><h3>Certificate Not Yet Issued</h3><p>The certificate becomes available after certification requirements are completed and the credential is issued.</p><button class="primary" onclick="go('cert')">VIEW CERTIFICATION REQUIREMENTS →</button></div>`;
 }
}

const originalGo=go;
go=function(id){originalGo(id);if(id==="rx")renderRx();if(id==="cert")renderCertification();if(id==="admin")renderAdmin()}

const goV431Base=go;go=function(page){goV431Base(page);if(page==="certificate")setTimeout(renderCertificateOnlyPage,0)};

const renderAdminAcaBase=renderAdmin;
renderAdmin=function(){
 renderAdminAcaBase();
 const root=document.getElementById("admin");
 if(!root||document.getElementById("acaTestAccessPanel"))return;
 const panel=document.createElement("div");panel.id="acaTestAccessPanel";panel.className="acaTestPanel";
 panel.innerHTML=`<div><span class="academyEyebrow">DEVELOPMENT / TESTING</span><h3>AIM-CA™ Test Access</h3><p>Temporarily unlock AIM-CA™ for authorized development testing. This does not change the production requirement for an ACTIVE AIM-CP™ credential.</p></div><button class="${aimCaTestUnlock()?"danger":"primary"}" onclick="setAimCaTestUnlock(${aimCaTestUnlock()?"false":"true"})">${aimCaTestUnlock()?"DISABLE TEST ACCESS":"ENABLE AIM-CA TEST ACCESS"}</button>`;
 const target=root.querySelector(".adminCenter")||root;target.appendChild(panel)
};
